35	#[derive(Clone, Debug)]
36	pub struct Label {
37	    pub text: String,
38	    pub x: f64,
39	    pub y: f64,
40	    pub tw: f64,
41	    pub fs: f64,
42	    // per-char advances in font units, and the font's units per em
43	    pub units: Vec<f64>,
44	    pub upem: f64,
45	    pub classes: Vec<String>,
46	    pub props: Vec<(String, Value)>,
47	}
48	
49	impl Label {
50	    // The cut-out as the id key sees it: the text width summed glyph by
51	    // glyph (each advance scaled on its own).
52	    pub fn cut_exact(&self) -> (f64, f64, f64, f64) {
53	        let mut tw = 0.0;
54	        for &u in &self.units {
55	            tw += u / self.upem * self.fs;
56	        }
57	        let w = tw + 2.0 * (0.3 * self.fs);
58	        let h = self.fs + 2.0 * (0.15 * self.fs);
59	        (self.x - w / 2.0, self.y - h / 2.0, w, h)
60	    }
61	    pub fn cut(&self) -> Rect {
62	        let w = self.tw + 0.6 * self.fs;
63	        let h = 1.3 * self.fs;
64	        Rect::new(self.x - w / 2.0, self.y - h / 2.0, self.x + w / 2.0, self.y + h / 2.0)
65	    }
66	    fn hit_box(&self) -> Rect {
67	        Rect::new(self.x - self.tw / 2.0 - 1.0, self.y - self.fs / 2.0 - 1.0, self.x + self.tw / 2.0 + 1.0, self.y + self.fs / 2.0 + 1.0)
68	    }
69	}
