88	// ------------------------------------------------------------ helpers
89	
90	fn set(props: &mut Vec<(String, Value)>, k: &str, v: &Value) {
91	    if let Some(e) = props.iter_mut().find(|e| e.0 == k) {
92	        e.1 = v.clone();
93	    } else {
94	        props.push((k.to_string(), v.clone()));
95	    }
96	}
97	
98	fn num_of(ctx: &Ctx, props: &[(String, Value)], k: &str) -> Option<f64> {
99	    get(props, k).and_then(|v| value_num(&ctx.sheet.env, v))
100	}
101	
102	fn ident_prop(props: &[(String, Value)], k: &str) -> Option<String> {
103	    get(props, k).and_then(|v| ident_of(v)).map(|s| s.to_string())
104	}
105	
106	// Ancestor chain of a node, root first, the node itself last.
107	fn chain(ctx: &Ctx, i: usize) -> Vec<usize> {
108	    let mut v = vec![i];
109	    let mut cur = i;
110	    while let Some(p) = ctx.nodes[cur].parent {
111	        v.push(p);
112	        cur = p;
113	    }
114	    v.reverse();
115	    v
116	}
117	
118	pub fn is_ancestor(ctx: &Ctx, anc: usize, i: usize) -> bool {
119	    let mut cur = i;
120	    while let Some(p) = ctx.nodes[cur].parent {
121	        if p == anc {
122	            return true;
123	        }
124	        cur = p;
125	    }
126	    false
127	}
128	
129	// Dotted id path of a node from the root.
130	pub fn path_of(ctx: &Ctx, i: usize) -> String {
131	    let mut parts = Vec::new();
132	    let mut cur = i;
133	    loop {
134	        if let Some(id) = &ctx.nodes[cur].id {
135	            parts.push(id.clone());
136	        }
137	        if cur == 0 {
138	            break;
139	        }
140	        let sc = ctx.nodes[cur].scope;
141	        if sc == cur {
142	            break;
143	        }
144	        cur = sc;
145	    }
146	    parts.reverse();
147	    parts.join(".")
148	}
149	
150	// Absolute centre of a node (translations only).
151	pub fn abs_center(ctx: &Ctx, i: usize) -> (f64, f64) {
152	    let mut x = 0.0;
153	    let mut y = 0.0;
154	    let mut cur = i;
155	    while cur != 0 {
156	        let n = &ctx.nodes[cur];
157	        let c = &ctx.comp[cur];
158	        x += n.x + c.translate.0;
159	        y += n.y + c.translate.1;
160	        match n.parent {
161	            Some(p) => cur = p,
162	            None => break,
163	        }
164	    }
165	    (x, y)
166	}
167	
168	// Absolute outer box of a node (stroke included).
169	pub fn abs_rect(ctx: &Ctx, i: usize) -> Rect {
170	    let (cx, cy) = abs_center(ctx, i);
171	    let (w, h) = crate::layout::outer(ctx, i);
172	    Rect::centered(cx, cy, w, h)
173	}
174	
175	// Inner box (no stroke): what labels keep off.
176	pub fn abs_inner(ctx: &Ctx, i: usize) -> Rect {
177	    let (cx, cy) = abs_center(ctx, i);
178	    let n = &ctx.nodes[i];
179	    Rect::new(cx - n.w / 2.0, cy - n.h / 2.0, cx + n.w / 2.0, cy + n.h / 2.0)
180	}
