182	// Split a link operator into (left end, line, right end).
183	pub fn split_op(op: &str) -> (String, String, String) {
184	    let chars: Vec<char> = op.chars().collect();
185	    let mut i = 0;
186	    let mut left = String::new();
187	    while i < chars.len() && chars[i] != '-' && chars[i] != '~' {
188	        left.push(chars[i]);
189	        i += 1;
190	    }
191	    let mut line = String::new();
192	    while i < chars.len() && (chars[i] == '-' || chars[i] == '~') {
193	        line.push(chars[i]);
194	        i += 1;
195	    }
196	    let right: String = chars[i..].iter().collect();
197	    (left, line, right)
198	}
