200	fn left_marker(s: &str) -> Option<String> {
201	    Some(
202	        match s {
203	            "<" => "arrow",
204	            "*" => "dot",
205	            ">" => "crow",
206	            "+" => "one",
207	            ">+" => "one-or-many",
208	            ">o" => "zero-or-many",
209	            "+o" => "zero-or-one",
210	            _ => return None,
211	        }
212	        .to_string(),
213	    )
214	}
215	
216	fn right_marker(s: &str) -> Option<String> {
217	    Some(
218	        match s {
219	            ">" => "arrow",
220	            "*" => "dot",
221	            "<" => "crow",
222	            "+" => "one",
223	            "+<" => "one-or-many",
224	            "o<" => "zero-or-many",
225	            "o+" => "zero-or-one",
226	            _ => return None,
227	        }
228	        .to_string(),
229	    )
230	}
