232	// ------------------------------------------------------------ style
233	
234	pub fn link_style(ctx: &Ctx, li: usize) -> LStyle {
235	    let l = &ctx.links[li];
236	    let mut props: Vec<(String, Value)> = Vec::new();
237	    let ch = chain(ctx, l.container);
238	    for &c in &ch {
239	        for k in ["clearance", "routing"] {
240	            if let Some(v) = ctx.nodes[c].props.get(k) {
241	                set(&mut props, k, v);
242	            }
243	        }
244	    }
245	    for d in &ctx.sheet.link_rules {
246	        set(&mut props, &d.name, &d.value);
247	    }
248	    let mut own: Vec<(String, Value)> = Vec::new();
249	    let mut label_props: Vec<(String, Value)> = Vec::new();
250	    for c in &l.classes {
251	        if let Some(cr) = ctx.sheet.class(c) {
252	            for d in &cr.decls {
253	                set(&mut props, &d.name, &d.value);
254	                set(&mut label_props, &d.name, &d.value);
255	            }
256	        }
257	    }
258	    for (id, ds) in &ctx.sheet.scoped_link_rules {
259	        if ch.iter().any(|&c| ctx.nodes[c].id.as_deref() == Some(id.as_str())) {
260	            for d in ds {
261	                set(&mut props, &d.name, &d.value);
262	                set(&mut own, &d.name, &d.value);
263	                set(&mut label_props, &d.name, &d.value);
264	            }
265	        }
266	    }
267	    for d in &l.style {
268	        set(&mut props, &d.name, &d.value);
269	        set(&mut own, &d.name, &d.value);
270	        set(&mut label_props, &d.name, &d.value);
271	    }
272	    let (lo, line, ro) = split_op(&l.op);
273	    let mut line_kind = match line.as_str() {
274	        "--" => "dashed",
275	        "---" => "dotted",
276	        "~" => "wavy",
277	        _ => "solid",
278	    }
279	    .to_string();
280	    if let Some(s) = ident_prop(&props, "stroke-style") {
281	        line_kind = s;
282	    }
283	    let mut start = left_marker(&lo);
284	    let mut end = right_marker(&ro);
285	    if let Some(m) = ident_prop(&props, "marker") {
286	        start = Some(m.clone());
287	        end = Some(m);
288	    }
289	    if let Some(m) = ident_prop(&props, "marker-start") {
290	        start = Some(m);
291	    }
292	    if let Some(m) = ident_prop(&props, "marker-end") {
293	        end = Some(m);
294	    }
295	    let norm = |m: Option<String>| m.filter(|s| s != "none" && crate::markers::is_known(s));
296	    let start = norm(start);
297	    let end = norm(end);
298	    let sw = num_of(ctx, &props, "stroke-width").unwrap_or(2.0);
299	    let k = num_of(ctx, &props, "clearance").unwrap_or(16.0);
300	    let radius = num_of(ctx, &props, "corner-radius");
301	    let routing = ident_prop(&props, "routing").unwrap_or_else(|| "orthogonal".to_string());
302	    let along = num_of(ctx, &props, "along");
303	    let font_size = num_of(ctx, &props, "font-size").unwrap_or(11.0);
304	    let weight = get(&props, "font-weight").map(weight_num).unwrap_or(400);
305	    let family = get(&props, "font-family").map(family_of);
306	    LStyle {
307	        props,
308	        own,
309	        label_props,
310	        sw,
311	        line: line_kind,
312	        start,
313	        end,
314	        k,
315	        radius,
316	        routing,
317	        along,
318	        font_size,
319	        weight,
320	        family,
321	    }
322	}
323	
324	// ------------------------------------------------------------ ordering
325	
326	// Links render container by container, depth first; within a container in
327	// statement order.
328	pub fn link_order(ctx: &Ctx) -> Vec<usize> {
329	    let mut order = Vec::new();
330	    let mut stack = vec![0usize];
331	    let mut visit: Vec<usize> = Vec::new();
332	    while let Some(n) = stack.pop() {
333	        visit.push(n);
334	        for &c in ctx.nodes[n].children.iter().rev() {
335	            stack.push(c);
336	        }
337	    }
338	    for n in visit {
339	        let mut here: Vec<usize> = (0..ctx.links.len()).filter(|&i| ctx.links[i].container == n).collect();
340	        here.sort_by_key(|&i| (ctx.links[i].stmt_index, i));
341	        order.extend(here);
342	    }
343	    order
344	}
345	
346	// Links drawn by a layout family (sequence, tree…) are not routed here.
347	pub fn family_owned(ctx: &Ctx, li: usize) -> bool {
348	    let l = &ctx.links[li];
349	    for &c in &chain(ctx, l.container) {
350	        let lay = ctx.comp[c].layout.as_str();
351	        if matches!(lay, "sequence" | "tree" | "mindmap" | "schematic" | "drawing" | "floorplan" | "chart" | "pie") {
352	            return true;
353	        }
354	        if ctx.nodes[c].is("mindmap") {
355	            return true;
356	        }
357	    }
358	    false
359	}
360	
361	// ------------------------------------------------------------ compute
362	
363	pub fn compute(ctx: &mut Ctx) {
364	    let order = link_order(ctx);
365	    let mut geos: Vec<LinkGeo> = Vec::new();
366	    let mut reqs: Vec<crate::wires::LinkReq> = Vec::new();
367	    for &li in &order {
368	        if family_owned(ctx, li) {
369	            continue;
370	        }
371	        let style = link_style(ctx, li);
372	        let l = &ctx.links[li];
373	        let pull_s = style.start.as_deref().map(|m| crate::markers::marker_full(m, (0.0, 0.0), (1.0, 0.0), style.sw).pull).unwrap_or(0.0);
374	        let pull_e = style.end.as_deref().map(|m| crate::markers::marker_full(m, (0.0, 0.0), (1.0, 0.0), style.sw).pull).unwrap_or(0.0);
375	        let from = promote(ctx, l.from, l.to, style.k);
376	        let to = promote(ctx, l.to, l.from, style.k);
377	        reqs.push(crate::wires::LinkReq {
378	            from,
379	            to,
380	            anchor_a: l.from_anchor.as_deref().and_then(Side::parse),
381	            anchor_b: l.to_anchor.as_deref().and_then(Side::parse),
382	            k: style.k,
383	            radius: style.radius.unwrap_or(style.k),
384	            routing: style.routing.clone(),
385	            stmt: l.stmt_index,
386	            pull_s: if pull_s > 0.0 { pull_s - 0.5 } else { 0.0 },
387	            pull_e: if pull_e > 0.0 { pull_e - 0.5 } else { 0.0 },
388	            mark_len_s: if style.start.is_some() { crate::markers::arrow_len(style.sw) } else { 0.0 },
389	            mark_len_e: if style.end.is_some() { crate::markers::arrow_len(style.sw) } else { 0.0 },
390	        });
391	        geos.push(LinkGeo { li, style, ..Default::default() });
392	    }
393	    // a link with both a label and a label block
394	    let mut warned: Vec<usize> = Vec::new();
395	    for &li in &order {
396	        let l = &ctx.links[li];
397	        if l.label.is_some() && !l.labels.is_empty() && !warned.contains(&l.stmt_index) {
398	            warned.push(l.stmt_index);
399	            let d = Diag::warning("validate", "keep a link's labels together \u{2014} write 'a -> b [ \"x\" \"y\" ]'", l.span);
400	            ctx.warnings.push(d);
401	        }
402	    }
403	    let world = World::new(ctx);
404	    let routed = route_all(ctx, &world, &reqs);
405	    for (g, r) in geos.iter_mut().zip(routed.into_iter()) {
406	        g.stray = r.stray;
407	        g.pts = r.pts;
408	        g.radii = r.radii;
409	        g.curve = r.curve;
410	        g.sa = r.sa;
411	        g.sb = r.sb;
412	    }
413	    // warnings for impossible links
414	    for g in &geos {
415	        if g.stray {
416	            let l = &ctx.links[g.li];
417	            let msg = format!(
418	                "impossible ({} {} {}): no legal route: every side entry or channel is closed at this layout",
419	                path_of(ctx, l.from),
420	                l.op,
421	                path_of(ctx, l.to)
422	            );
423	            ctx.warnings.push(Diag::warning("impossible-link", &msg, l.span));
424	        }
425	    }
426	    place_labels(ctx, &world, &mut geos);
427	    compute_masks(&mut geos);
428	    ctx.link_geo = geos;
429	}
