431	// Gap between two boxes (negative when they overlap).
432	fn box_gap(a: &Rect, b: &Rect) -> f64 {
433	    (b.x0 - a.x1).max(a.x0 - b.x1).max(b.y0 - a.y1).max(a.y0 - b.y1)
434	}
435	
436	// A node packed closer than the clearance to a sibling cannot be reached on
437	// its own from outside its container: the wire attaches to the container.
438	pub fn promote(ctx: &Ctx, n: usize, other: usize, k: f64) -> usize {
439	    let mut cur = n;
440	    loop {
441	        let Some(p) = ctx.nodes[cur].parent else { return cur };
442	        if p == 0 || p == other || is_ancestor(ctx, p, other) {
443	            return cur;
444	        }
445	        let me = abs_rect(ctx, cur);
446	        let packed = ctx.nodes[p].children.iter().any(|&s| {
447	            s != cur && ctx.nodes[s].prim != Prim::Text && ctx.comp[s].pin.is_none() && box_gap(&me, &abs_rect(ctx, s)) < k
448	        });
449	        if !packed {
450	            return cur;
451	        }
452	        cur = p;
453	    }
454	}
