456	// The scene as seen by the router: absolute boxes for every node.
457	pub struct World {
458	    pub rects: Vec<Rect>,
459	}
460	
461	impl World {
462	    pub fn new(ctx: &Ctx) -> World {
463	        let rects: Vec<Rect> = (0..ctx.nodes.len()).map(|i| abs_rect(ctx, i)).collect();
464	        if std::env::var("LINI_DBG_RECT").is_ok() {
465	            for (i, r) in rects.iter().enumerate() {
466	                let (w, h) = crate::layout::outer(ctx, i);
467	                eprintln!("RECT {} {:?} x={:?} y={:?} w={:?} h={:?} nw={:?} nh={:?}", i, ctx.nodes[i].id, ctx.nodes[i].x, ctx.nodes[i].y, w, h, ctx.nodes[i].w, ctx.nodes[i].h);
468	                let _ = r;
469	            }
470	        }
471	        World { rects }
472	    }
473	}
474	
475	pub fn is_obstacle_kind(ctx: &Ctx, i: usize) -> bool {
476	    let n = &ctx.nodes[i];
477	    if n.prim == Prim::Text {
478	        return false;
479	    }
480	    if ctx.comp[i].pin.is_some() && !n.is("caption") {
481	        return false;
482	    }
483	    true
484	}
485	
486	// Obstacles for a link between `a` and `b`: maximal nodes that hold neither
487	// endpoint; containers of an endpoint become walls.
488	pub fn obstacles(ctx: &Ctx, world: &World, a: usize, b: usize) -> Vec<Ob> {
489	    let mut out = Vec::new();
490	    let mut stack: Vec<usize> = ctx.nodes[0].children.clone();
491	    while let Some(n) = stack.pop() {
492	        if n == a || n == b {
493	            continue;
494	        }
495	        if !is_obstacle_kind(ctx, n) {
496	            continue;
497	        }
498	        let ha = is_ancestor(ctx, n, a);
499	        let hb = is_ancestor(ctx, n, b);
500	        if ha || hb {
501	            let kind = if ha && hb {
502	                ObKind::WallBoth
503	            } else if ha {
504	                ObKind::WallA
505	            } else {
506	                ObKind::WallB
507	            };
508	            out.push(Ob { r: world.rects[n], kind, node: n });
509	            for &c in &ctx.nodes[n].children {
510	                stack.push(c);
511	            }
512	        } else {
513	            out.push(Ob { r: world.rects[n], kind: ObKind::Solid, node: n });
514	            // a container's caption sits outside its box
515	            for &c in &ctx.nodes[n].children {
516	                if ctx.comp[c].pin.is_some() && ctx.nodes[c].is("caption") && c != a && c != b {
517	                    out.push(Ob { r: world.rects[c], kind: ObKind::Solid, node: c });
518	                }
519	            }
520	        }
521	    }
522	    out.sort_by_key(|o| o.node);
523	    out
524	}
