539	// ------------------------------------------------------------ labels
540	
541	fn poly_len(pts: &[(f64, f64)]) -> f64 {
542	    let mut t = 0.0;
543	    for w in pts.windows(2) {
544	        t += ((w[1].0 - w[0].0).powi(2) + (w[1].1 - w[0].1).powi(2)).sqrt();
545	    }
546	    t
547	}
548	
549	fn point_at(pts: &[(f64, f64)], s: f64) -> (f64, f64) {
550	    let mut acc = 0.0;
551	    for w in pts.windows(2) {
552	        let l = ((w[1].0 - w[0].0).powi(2) + (w[1].1 - w[0].1).powi(2)).sqrt();
553	        if acc + l >= s && l > 0.0 {
554	            let t = (s - acc) / l;
555	            return (w[0].0 + (w[1].0 - w[0].0) * t, w[0].1 + (w[1].1 - w[0].1) * t);
556	        }
557	        acc += l;
558	    }
559	    *pts.last().unwrap_or(&(0.0, 0.0))
560	}
561	
562	fn label_family(ctx: &Ctx, st: &LStyle) -> Family {
563	    st.family.unwrap_or(ctx.comp[0].family)
564	}
565	
566	fn label_texts(ctx: &Ctx, li: usize) -> Vec<(String, Vec<String>, Vec<Decl>)> {
567	    let l = &ctx.links[li];
568	    let mut v = Vec::new();
569	    if let Some(t) = &l.label {
570	        v.push((t.clone(), vec![], vec![]));
571	    }
572	    for s in &l.labels {
573	        if let Stmt::Text(t) = s {
574	            v.push((t.text.clone(), t.classes.clone(), t.style.clone().unwrap_or_default()));
575	        }
576	    }
577	    v
578	}
