580	fn place_labels(ctx: &Ctx, world: &World, geos: &mut [LinkGeo]) {
581	    // label keep-out: every leaf box
582	    let mut keep: Vec<Rect> = Vec::new();
583	    for i in 1..ctx.nodes.len() {
584	        let n = &ctx.nodes[i];
585	        if n.prim == Prim::Text {
586	            continue;
587	        }
588	        if n.children.iter().any(|&c| ctx.nodes[c].prim != Prim::Text && ctx.comp[c].pin.is_none()) {
589	            continue;
590	        }
591	        let _ = world;
592	        keep.push(abs_inner(ctx, i));
593	    }
594	    let mut placed: Vec<Rect> = Vec::new();
595	    for g in geos.iter_mut() {
596	        if g.stray || g.pts.len() < 2 {
597	            continue;
598	        }
599	        let texts = label_texts(ctx, g.li);
600	        if texts.is_empty() {
601	            continue;
602	        }
603	        let total = poly_len(&g.pts);
604	        let n = texts.len();
605	        let fam = label_family(ctx, &g.style);
606	        for (k, (text, classes, style)) in texts.into_iter().enumerate() {
607	            let mut props: Vec<(String, Value)> = g.style.label_props.iter().filter(|(k, _)| k != "translate" && k != "rotate").cloned().collect();
608	            for c in &classes {
609	                if let Some(cr) = ctx.sheet.class(c) {
610	                    for d in &cr.decls {
611	                        set(&mut props, &d.name, &d.value);
612	                    }
613	                }
614	            }
615	            for d in &style {
616	                set(&mut props, &d.name, &d.value);
617	            }
618	            let fs = num_of(ctx, &props, "font-size").unwrap_or(g.style.font_size);
619	            let wt = get(&props, "font-weight").map(weight_num).unwrap_or(g.style.weight);
620	            let tw = crate::font::text_width(fam, wt, fs, &text);
621	            let fnt = crate::font::font(fam, wt);
622	            let units: Vec<f64> = text.chars().map(|c| crate::font::char_advance_em(fam, wt, c) * fnt.upem).collect();
623	            let upem = fnt.upem;
624	            let frac = if n == 1 {
625	                g.style.along.unwrap_or(0.5)
626	            } else {
627	                ((k as f64 + 1.0) / (n as f64 + 1.0) * 100.0).round() / 100.0
628	            };
629	            let s0 = frac * total;
630	            let mk = |s: f64| {
631	                let (x, y) = point_at(&g.pts, s);
632	                Label { text: text.clone(), x, y, tw, fs, units: units.clone(), upem, classes: classes.clone(), props: props.clone() }
633	            };
634	            let ok = |lb: &Label| {
635	                let c = lb.cut();
636	                let hb = lb.hit_box();
637	                !keep.iter().any(|r| r.overlaps(&c)) && !placed.iter().any(|r| r.overlaps(&hb))
638	            };
639	            let mut chosen = mk(s0);
640	            if !ok(&chosen) {
641	                let mut step = 1;
642	                let mut found = None;
643	                loop {
644	                    let d = 4.0 * step as f64;
645	                    if s0 + d > total + 1e-9 && s0 - d < -1e-9 {
646	                        break;
647	                    }
648	                    for s in [s0 + d, s0 - d] {
649	                        if s < -1e-9 || s > total + 1e-9 {
650	                            continue;
651	                        }
652	                        let lb = mk(s);
653	                        if ok(&lb) {
654	                            found = Some(lb);
655	                            break;
656	                        }
657	                    }
658	                    if found.is_some() {
659	                        break;
660	                    }
661	                    step += 1;
662	                }
663	                if let Some(lb) = found {
664	                    chosen = lb;
665	                }
666	            }
667	            placed.push(chosen.hit_box());
668	            // a label's own translate nudges it off its place on the wire
669	            if let Some(v) = get(&chosen.props, "translate") {
670	                let xs = crate::style::value_nums(&ctx.sheet.env, v);
671	                if xs.len() == 2 {
672	                    chosen.x += xs[0];
673	                    chosen.y += xs[1];
674	                }
675	            }
676	            g.labels.push(chosen);
677	        }
678	    }
679	}
