681	// The wire's box, grown by half the stroke plus one.
682	fn mask_box(g: &LinkGeo) -> Rect {
683	    let mut x0 = f64::INFINITY;
684	    let mut y0 = f64::INFINITY;
685	    let mut x1 = f64::NEG_INFINITY;
686	    let mut y1 = f64::NEG_INFINITY;
687	    for &(x, y) in &g.pts {
688	        x0 = x0.min(x);
689	        y0 = y0.min(y);
690	        x1 = x1.max(x);
691	        y1 = y1.max(y);
692	    }
693	    // a wavy wire also swings by its amplitude
694	    let m = g.style.sw / 2.0 + 1.0 + if g.style.line == "wavy" { 1.4 } else { 0.0 };
695	    Rect::new(x0 - m, y0 - m, x1 + m, y1 + m)
696	}
