698	// The mask id hashes the background box and the cut-outs at full
699	// precision, as `x y w h [(x, y, w, h), ...]` with debug-formatted floats.
700	fn mask_key(mb: &Rect, cuts: &[(f64, f64, f64, f64)]) -> String {
701	    format!("{:?} {:?} {:?} {:?} {:?}", mb.x0, mb.y0, mb.w(), mb.h(), cuts)
702	}
