704	fn compute_masks(geos: &mut [LinkGeo]) {
705	    let all: Vec<(usize, usize, Rect)> = geos
706	        .iter()
707	        .enumerate()
708	        .flat_map(|(gi, g)| g.labels.iter().enumerate().map(move |(k, lb)| (gi, k, lb.cut())))
709	        .collect();
710	    for g in geos.iter_mut() {
711	        if g.stray || g.pts.len() < 2 {
712	            continue;
713	        }
714	        let mb = mask_box(g);
715	        g.cuts = all.iter().filter(|(_, _, r)| r.overlaps(&mb)).map(|(gi, k, _)| (*gi, *k)).collect();
716	    }
717	}
