721	// The link's bounds for the viewBox: the wire plus its label text boxes.
722	pub fn extend_bbox(ctx: &Ctx, b: &mut [f64; 4]) {
723	    for g in &ctx.link_geo {
724	        for &(x, y) in &g.pts {
725	            b[0] = b[0].min(x);
726	            b[1] = b[1].min(y);
727	            b[2] = b[2].max(x);
728	            b[3] = b[3].max(y);
729	        }
730	        if let Some(c) = &g.curve {
731	            for &(x, y) in c.iter() {
732	                b[0] = b[0].min(x);
733	                b[1] = b[1].min(y);
734	                b[2] = b[2].max(x);
735	                b[3] = b[3].max(y);
736	            }
737	        }
738	        for lb in &g.labels {
739	            b[0] = b[0].min(lb.x - lb.tw / 2.0);
740	            b[1] = b[1].min(lb.y - lb.fs / 2.0);
741	            b[2] = b[2].max(lb.x + lb.tw / 2.0);
742	            b[3] = b[3].max(lb.y + lb.fs / 2.0);
743	        }
744	    }
745	}
