751	// Wire endpoints after marker pull-back, and the markers themselves.
752	struct Ends {
753	    s: (f64, f64),
754	    e: (f64, f64),
755	    marks: Vec<String>,
756	    open: bool,
757	    any: bool,
758	}
759	
760	fn ends_and_markers(g: &LinkGeo, first: (f64, f64), second: (f64, f64), penult: (f64, f64), last: (f64, f64)) -> Ends {
761	    let sw = g.style.sw;
762	    let mut marks = Vec::new();
763	    let mut open = false;
764	    let mut any = false;
765	    let mut s = first;
766	    let mut e = last;
767	    // a pull-back longer than its end segment is dropped (the wire keeps
768	    // running to the outline)
769	    let dist = |a: (f64, f64), b: (f64, f64)| ((a.0 - b.0).powi(2) + (a.1 - b.1).powi(2)).sqrt();
770	    let pull_of = |m: &Option<String>| m.as_deref().map(|k| crate::markers::marker_full(k, (0.0, 0.0), (1.0, 0.0), sw).pull).unwrap_or(0.0);
771	    let pe = (pull_of(&g.style.end) - 0.5).max(0.0);
772	    let ps = (pull_of(&g.style.start) - 0.5).max(0.0);
773	    let single = g.pts.len() == 2 && g.curve.is_none();
774	    let drop_e = pe > dist(penult, last) + 1e-9;
775	    let drop_s = if single { ps > dist(first, second) - if drop_e { 0.0 } else { pe } + 1e-9 } else { ps > dist(first, second) + 1e-9 };
776	    if let Some(m) = &g.style.start {
777	        let u = unitv(second, first); // into the start node
778	        let tip = (first.0 + u.0 * 0.5, first.1 + u.1 * 0.5);
779	        let mk = crate::markers::marker_full(m, tip, u, sw);
780	        if mk.pull > 0.0 && !drop_s {
781	            s = (tip.0 - u.0 * mk.pull, tip.1 - u.1 * mk.pull);
782	        }
783	        open |= mk.open;
784	        any = true;
785	        marks.extend(mk.elems);
786	    }
787	    if let Some(m) = &g.style.end {
788	        let u = unitv(penult, last);
789	        let tip = (last.0 + u.0 * 0.5, last.1 + u.1 * 0.5);
790	        let mk = crate::markers::marker_full(m, tip, u, sw);
791	        if mk.pull > 0.0 && !drop_e {
792	            e = (tip.0 - u.0 * mk.pull, tip.1 - u.1 * mk.pull);
793	        }
794	        open |= mk.open;
795	        any = true;
796	        marks.extend(mk.elems);
797	    }
798	    Ends { s, e, marks, open, any }
799	}
