805	// SVG path data for the orthogonal wire with rounded corners.
806	fn ortho_d(pts: &[(f64, f64)], radii: &[f64]) -> String {
807	    let mut d = format!("M {} {}", f4(pts[0].0), f4(pts[0].1));
808	    let n = pts.len();
809	    for i in 1..n - 1 {
810	        let p = pts[i - 1];
811	        let c = pts[i];
812	        let q = pts[i + 1];
813	        let u0 = unitv(p, c);
814	        let u1 = unitv(c, q);
815	        let r = radii.get(i - 1).copied().unwrap_or(0.0);
816	        let a = (c.0 - u0.0 * r, c.1 - u0.1 * r);
817	        let b = (c.0 + u1.0 * r, c.1 + u1.1 * r);
818	        let sweep = if cross(u0, u1) > 0.0 { 1 } else { 0 };
819	        d.push_str(&format!(" L {} {} A {} {} 0 0 {} {} {}", f4(a.0), f4(a.1), f4(r), f4(r), sweep, f4(b.0), f4(b.1)));
820	    }
821	    d.push_str(&format!(" L {} {}", f4(pts[n - 1].0), f4(pts[n - 1].1)));
822	    d
823	}
