825	// Wavy wire: a tapered sine sampled every quarter wave, joined by cubic
826	// segments whose handles follow the curve's tangent.
827	fn wave_d(p0: (f64, f64), p1: (f64, f64)) -> String {
828	    let l = ((p1.0 - p0.0).powi(2) + (p1.1 - p0.1).powi(2)).sqrt();
829	    let u = unitv(p0, p1);
830	    let nrm = (-u.1, u.0);
831	    let amp = 1.4;
832	    let lam = 12.0;
833	    let ramp = 6.0;
834	    let n = ((l / 3.0).round() as usize).max(1);
835	    let h = l / n as f64;
836	    let ss = |t: f64| {
837	        let t = t.clamp(0.0, 1.0);
838	        3.0 * t * t - 2.0 * t * t * t
839	    };
840	    let dss = |t: f64| if t <= 0.0 || t >= 1.0 { 0.0 } else { 6.0 * t - 6.0 * t * t };
841	    let w = 2.0 * std::f64::consts::PI / lam;
842	    let mut samples = Vec::new();
843	    for i in 0..=n {
844	        let x = i as f64 * h;
845	        let e1 = ss(x / ramp);
846	        let e2 = ss((l - x) / ramp);
847	        let (e, de) = if e1 < e2 { (e1, dss(x / ramp) / ramp) } else { (e2, -dss((l - x) / ramp) / ramp) };
848	        let y = amp * e * (w * x).sin();
849	        let dy = amp * (de * (w * x).sin() + e * w * (w * x).cos());
850	        samples.push((x, y, dy));
851	    }
852	    let to = |x: f64, y: f64| (p0.0 + u.0 * x + nrm.0 * y, p0.1 + u.1 * x + nrm.1 * y);
853	    let mut d = format!("M {} {}", f4(p0.0), f4(p0.1));
854	    for i in 0..n {
855	        let (xa, ya, da) = samples[i];
856	        let (xb, yb, db) = samples[i + 1];
857	        let ch = ((xb - xa).powi(2) + (yb - ya).powi(2)).sqrt() / 3.0;
858	        let la = (1.0 + da * da).sqrt();
859	        let lb = (1.0 + db * db).sqrt();
860	        let c1 = to(xa + ch / la, ya + da / la * ch);
861	        let c2 = to(xb - ch / lb, yb - db / lb * ch);
862	        let e = to(xb, yb);
863	        d.push_str(&format!(" C {} {} {} {} {} {}", f4(c1.0), f4(c1.1), f4(c2.0), f4(c2.1), f4(e.0), f4(e.1)));
864	    }
865	    d
866	}
