933	// The straight line between two boxes, clipped to their outlines.
934	pub fn stray_line(a: &Rect, b: &Rect) -> ((f64, f64), (f64, f64)) {
935	    let c0 = (a.cx(), a.cy());
936	    let c1 = (b.cx(), b.cy());
937	    (clip_out(a, c0, c1), clip_out(b, c1, c0))
938	}
939	
940	fn clip_out(r: &Rect, c: (f64, f64), toward: (f64, f64)) -> (f64, f64) {
941	    let dx = toward.0 - c.0;
942	    let dy = toward.1 - c.1;
943	    let mut t = f64::INFINITY;
944	    if dx.abs() > 1e-12 {
945	        t = t.min((r.w() / 2.0) / dx.abs());
946	    }
947	    if dy.abs() > 1e-12 {
948	        t = t.min((r.h() / 2.0) / dy.abs());
949	    }
950	    if !t.is_finite() {
951	        return c;
952	    }
953	    (c.0 + dx * t, c.1 + dy * t)
954	}
