969	pub fn render(ctx: &Ctx, out: &mut Out) -> Result<String, Diag> {
970	    let geos = &ctx.link_geo;
971	    if geos.is_empty() {
972	        return Ok("  <g class=\"lini-links\"/>\n".to_string());
973	    }
974	    let rules = rule_set(ctx);
975	    let mut s = String::from("  <g class=\"lini-links\">\n");
976	    let mut any_link = false;
977	    let mut any_label = false;
978	    let mut any_mask = false;
979	    let mut any_marker = false;
980	    let mut any_open = false;
981	    let mut dashed = false;
982	    let mut dotted = false;
983	    let mut class_marker: Vec<String> = Vec::new();
984	    for (gi, g) in geos.iter().enumerate() {
985	        let l = &ctx.links[g.li];
986	        if g.stray {
987	            stray_svg(ctx, g, &mut s, out);
988	            continue;
989	        }
990	        any_link = true;
991	        let st = &g.style;
992	        let mut cls = vec!["lini-link".to_string()];
993	        match st.line.as_str() {
994	            "dashed" => {
995	                cls.push("lini-link-dashed".into());
996	                dashed = true;
997	            }
998	            "dotted" => {
999	                cls.push("lini-link-dotted".into());
1000	                dotted = true;
1001	            }
1002	            _ => {}
1003	        }
1004	        for c in &l.classes {
1005	            cls.push(format!("lini-style-{}", c));
1006	            if !out.used_classes.contains(c) {
1007	                out.used_classes.push(c.clone());
1008	            }
1009	        }
1010	        // inline style: own stroke decls
1011	        let mut inline: Vec<(String, String)> = Vec::new();
1012	        let mut tmpvars = Vec::new();
1013	        for k in ["stroke", "stroke-width", "opacity"] {
1014	            if let Some(v) = get(&st.own, k) {
1015	                match k {
1016	                    "stroke" => {
1017	                        if let Some(t) = single_term(v) {
1018	                            inline.push((k.into(), color_css(t, &mut tmpvars, v.span)?));
1019	                        }
1020	                    }
1021	                    _ => {
1022	                        if let Some(x) = value_num(&ctx.sheet.env, v) {
1023	                            inline.push((k.into(), f4(x)));
1024	                        }
1025	                    }
1026	                }
1027	            }
1028	        }
1029	        if matches!(st.line.as_str(), "dashed" | "dotted") && (get(&st.own, "stroke-width").is_some() || get(&st.own, "stroke-style").is_some()) {
1030	            if let (Some(dv), Some(rv)) = (dasharray(&st.line, st.sw), dasharray(&st.line, rules.sw)) {
1031	                if dv != rv {
1032	                    inline.push(("stroke-dasharray".into(), dv));
1033	                }
1034	            }
1035	        }
1036	        for v in tmpvars {
1037	            use_var(&mut out.vars, &v);
