1	// Orthogonal link routing: a sparse-grid search over obstacles inflated by
2	// the clearance, then segment placement (staircase segments centre in their
3	// channel, detours hug what they go around), port spreading along shared
4	// sides and track spreading for parallel runs.
5	
6	use std::collections::BinaryHeap;
7	
8	pub const EPS: f64 = 1e-6;
9	
10	// A box. Edges are kept for geometry; the centre and size are kept exactly
11	// as laid out so ports and side lengths match the layout's arithmetic.
12	#[derive(Clone, Copy, Debug, PartialEq)]
13	pub struct Rect {
14	    pub x0: f64,
15	    pub y0: f64,
16	    pub x1: f64,
17	    pub y1: f64,
18	    pub ccx: f64,
19	    pub ccy: f64,
20	    pub cw: f64,
21	    pub ch: f64,
22	}
23	
24	impl Rect {
25	    pub fn new(x0: f64, y0: f64, x1: f64, y1: f64) -> Rect {
26	        Rect { x0, y0, x1, y1, ccx: (x0 + x1) / 2.0, ccy: (y0 + y1) / 2.0, cw: x1 - x0, ch: y1 - y0 }
27	    }
28	    pub fn centered(cx: f64, cy: f64, w: f64, h: f64) -> Rect {
29	        Rect { x0: cx - w / 2.0, y0: cy - h / 2.0, x1: cx + w / 2.0, y1: cy + h / 2.0, ccx: cx, ccy: cy, cw: w, ch: h }
30	    }
31	    pub fn grow(&self, k: f64) -> Rect {
32	        Rect {
33	            x0: self.x0 - k,
34	            y0: self.y0 - k,
35	            x1: self.x1 + k,
36	            y1: self.y1 + k,
37	            ccx: self.ccx,
38	            ccy: self.ccy,
39	            cw: self.cw + 2.0 * k,
40	            ch: self.ch + 2.0 * k,
41	        }
42	    }
43	    pub fn cx(&self) -> f64 {
44	        self.ccx
45	    }
46	    pub fn cy(&self) -> f64 {
47	        self.ccy
48	    }
49	    pub fn w(&self) -> f64 {
50	        self.cw
51	    }
52	    pub fn h(&self) -> f64 {
53	        self.ch
54	    }
55	    pub fn overlaps(&self, o: &Rect) -> bool {
56	        self.x0 < o.x1 && o.x0 < self.x1 && self.y0 < o.y1 && o.y0 < self.y1
57	    }
58	    pub fn contains_open(&self, x: f64, y: f64) -> bool {
59	        x > self.x0 + EPS && x < self.x1 - EPS && y > self.y0 + EPS && y < self.y1 - EPS
60	    }
61	}
