63	// Sides, clockwise from the top; the direction is the outward normal.
64	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
65	pub enum Side {
66	    Top,
67	    Right,
68	    Bottom,
69	    Left,
70	}
71	
72	pub const SIDES: [Side; 4] = [Side::Top, Side::Right, Side::Bottom, Side::Left];
73	
74	impl Side {
75	    pub fn dir(self) -> (f64, f64) {
76	        match self {
77	            Side::Top => (0.0, -1.0),
78	            Side::Right => (1.0, 0.0),
79	            Side::Bottom => (0.0, 1.0),
80	            Side::Left => (-1.0, 0.0),
81	        }
82	    }
83	    pub fn horizontal(self) -> bool {
84	        matches!(self, Side::Top | Side::Bottom)
85	    }
86	    pub fn parse(s: &str) -> Option<Side> {
87	        match s {
88	            "top" => Some(Side::Top),
89	            "right" => Some(Side::Right),
90	            "bottom" => Some(Side::Bottom),
91	            "left" => Some(Side::Left),
92	            _ => None,
93	        }
94	    }
95	    pub fn idx(self) -> usize {
96	        match self {
97	            Side::Top => 0,
98	            Side::Right => 1,
99	            Side::Bottom => 2,
100	            Side::Left => 3,
101	        }
102	    }
103	}
