105	// The point on a rect side at the given offset from the side's centre
106	// (along x for top/bottom, along y for left/right).
107	pub fn side_point(r: &Rect, s: Side, off: f64) -> (f64, f64) {
108	    match s {
109	        Side::Top => (r.cx() + off, r.y0),
110	        Side::Bottom => (r.cx() + off, r.y1),
111	        Side::Left => (r.x0, r.cy() + off),
112	        Side::Right => (r.x1, r.cy() + off),
113	    }
114	}
115	
116	// Extent of a side: (start, end) along its axis.
117	pub fn side_span(r: &Rect, s: Side) -> (f64, f64) {
118	    if s.horizontal() {
119	        (r.x0, r.x1)
120	    } else {
121	        (r.y0, r.y1)
122	    }
123	}
