150	// Directions as indices: 0 right, 1 down, 2 left, 3 up.
151	fn dir_of(dx: f64, dy: f64) -> usize {
152	    if dx > EPS {
153	        0
154	    } else if dy > EPS {
155	        1
156	    } else if dx < -EPS {
157	        2
158	    } else {
159	        3
160	    }
161	}
