172	impl Env {
173	    // Inflated solid obstacles (including the two endpoints).
174	    pub fn solids(&self) -> Vec<Rect> {
175	        let mut v: Vec<Rect> = self.obs.iter().filter(|o| o.kind != ObKind::WallBoth).map(|o| o.r.grow(self.k)).collect();
176	        v.push(self.a.grow(self.k));
177	        v.push(self.b.grow(self.k));
178	        v
179	    }
180	}
