182	// Is the axis-aligned segment p-q clear of every inflated solid's interior?
183	fn seg_clear(solids: &[Rect], p: (f64, f64), q: (f64, f64)) -> bool {
184	    let (x0, x1) = if p.0 < q.0 { (p.0, q.0) } else { (q.0, p.0) };
185	    let (y0, y1) = if p.1 < q.1 { (p.1, q.1) } else { (q.1, p.1) };
186	    for r in solids {
187	        if (y1 - y0).abs() < EPS {
188	            // horizontal
189	            if y0 > r.y0 + EPS && y0 < r.y1 - EPS && x0 < r.x1 - EPS && x1 > r.x0 + EPS {
190	                return false;
191	            }
192	        } else if (x1 - x0).abs() < EPS {
193	            if x0 > r.x0 + EPS && x0 < r.x1 - EPS && y0 < r.y1 - EPS && y1 > r.y0 + EPS {
194	                return false;
195	            }
196	        }
197	    }
198	    true
199	}
