201	// Wall bands: a container that holds an endpoint may be crossed, but only
202	// head-on; nothing runs along or turns within the clearance of its border.
203	pub struct Band {
204	    // the band region (open): the ring just outside a wall's border
205	    r: Rect,
206	    // true: the border is horizontal (top/bottom edge) — vertical crossing allowed
207	    horiz: bool,
208	    // crossings must fall within this span (along the border)
209	    lo: f64,
210	    hi: f64,
211	}
212	
213	fn wall_bands(env: &Env) -> Vec<Band> {
214	    let k = env.k;
215	    let mut v = Vec::new();
216	    for o in &env.obs {
217	        if o.kind != ObKind::WallBoth {
218	            continue;
219	        }
220	        let r = o.r;
221	        v.push(Band { r: Rect::new(r.x0 - k, r.y0 - k, r.x1 + k, r.y0), horiz: true, lo: r.x0 + k, hi: r.x1 - k });
222	        v.push(Band { r: Rect::new(r.x0 - k, r.y1, r.x1 + k, r.y1 + k), horiz: true, lo: r.x0 + k, hi: r.x1 - k });
223	        v.push(Band { r: Rect::new(r.x0 - k, r.y0 - k, r.x0, r.y1 + k), horiz: false, lo: r.y0 + k, hi: r.y1 - k });
224	        v.push(Band { r: Rect::new(r.x1, r.y0 - k, r.x1 + k, r.y1 + k), horiz: false, lo: r.y0 + k, hi: r.y1 - k });
225	    }
226	    v
227	}
