233	// A segment may cross a band only perpendicular to its border, away from
234	// the border's ends.
235	fn seg_band_ok(bands: &[Band], p: (f64, f64), q: (f64, f64)) -> bool {
236	    let horiz_seg = (p.1 - q.1).abs() < EPS;
237	    let (x0, x1) = if p.0 < q.0 { (p.0, q.0) } else { (q.0, p.0) };
238	    let (y0, y1) = if p.1 < q.1 { (p.1, q.1) } else { (q.1, p.1) };
239	    for b in bands {
240	        let r = &b.r;
241	        let inter = if horiz_seg {
242	            y0 > r.y0 + EPS && y0 < r.y1 - EPS && x0 < r.x1 - EPS && x1 > r.x0 + EPS
243	        } else {
244	            x0 > r.x0 + EPS && x0 < r.x1 - EPS && y0 < r.y1 - EPS && y1 > r.y0 + EPS
245	        };
246	        if !inter {
247	            continue;
248	        }
249	        // a horizontal border is crossed by vertical segments only
250	        if b.horiz == horiz_seg {
251	            return false;
252	        }
253	        let at = if horiz_seg { y0 } else { x0 };
254	        if at < b.lo - EPS || at > b.hi + EPS {
255	            return false;
256	        }
257	    }
258	    true
259	}
