269	fn uniq(mut v: Vec<f64>) -> Vec<f64> {
270	    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
271	    let mut o: Vec<f64> = Vec::new();
272	    for x in v {
273	        if o.last().map_or(true, |l| (x - *l).abs() > 1e-7) {
274	            o.push(x);
275	        }
276	    }
277	    o
278	}
