280	#[derive(PartialEq)]
281	struct HeapItem {
282	    cost: f64,
283	    seq: u64,
284	    state: usize,
285	}
286	impl Eq for HeapItem {}
287	impl PartialOrd for HeapItem {
288	    fn partial_cmp(&self, o: &Self) -> Option<std::cmp::Ordering> {
289	        Some(self.cmp(o))
290	    }
291	}
292	impl Ord for HeapItem {
293	    fn cmp(&self, o: &Self) -> std::cmp::Ordering {
294	        // min-heap on cost, then on insertion order
295	        o.cost.partial_cmp(&self.cost).unwrap_or(std::cmp::Ordering::Equal).then(self.seq.cmp(&o.seq))
296	    }
297	}
