307	// Free width across an axis-aligned segment: the gap between the inflated
308	// obstacles on either side over the segment's span.
309	pub fn free_width(solids: &[Rect], p: (f64, f64), q: (f64, f64)) -> f64 {
310	    let horiz = (p.1 - q.1).abs() < 1e-9;
311	    let (lo_s, hi_s) = if horiz { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
312	    let pos = if horiz { p.1 } else { p.0 };
313	    let mut lo = f64::NEG_INFINITY;
314	    let mut hi = f64::INFINITY;
315	    for r in solids {
316	        let (a0, a1, b0, b1) = if horiz { (r.x0, r.x1, r.y0, r.y1) } else { (r.y0, r.y1, r.x0, r.x1) };
317	        if a0 < hi_s - EPS && a1 > lo_s + EPS {
318	            if b1 <= pos + EPS && b1 > lo {
319	                lo = b1;
320	            }
321	            if b0 >= pos - EPS && b0 < hi {
322	                hi = b0;
323	            }
324	        }
325	    }
326	    hi - lo
327	}
