329	// The straight stub leaving an endpoint side: out of the endpoint's own
330	// clearance and through every container that holds only this end, ending
331	// the clearance beyond the outermost border. None when blocked.
332	pub fn stub(env: &Env, solids: &[Rect], bands: &[Band], first: bool, sd: Side) -> Option<((f64, f64), (f64, f64))> {
333	    let k = env.k;
334	    let node = if first { env.a } else { env.b };
335	    let other = if first { env.b } else { env.a };
336	    let wall_kind = if first { ObKind::WallA } else { ObKind::WallB };
337	    let p = side_point(&node, sd, 0.0);
338	    let d = sd.dir();
339	    let mut ext: f64 = 0.0;
340	    let mut walls: Vec<Rect> = Vec::new();
341	    for o in &env.obs {
342	        if o.kind != wall_kind {
343	            continue;
344	        }
345	        let w = o.r;
346	        let dist = match sd {
347	            Side::Right => w.x1 - p.0,
348	            Side::Left => p.0 - w.x0,
349	            Side::Bottom => w.y1 - p.1,
350	            Side::Top => p.1 - w.y0,
351	        };
352	        // the crossing keeps the clearance from the border's ends
353	        let (lo, hi, at) = if sd.horizontal() { (w.x0 + k, w.x1 - k, p.0) } else { (w.y0 + k, w.y1 - k, p.1) };
354	        if at < lo - EPS || at > hi + EPS {
355	            return None;
356	        }
357	        ext = ext.max(dist);
358	        walls.push(w.grow(k));
359	    }
360	    let len = ext + k;
361	    let e = (p.0 + d.0 * len, p.1 + d.1 * len);
362	    // clear of everything but the walls it crosses and its own node
363	    let own = node.grow(k);
364	    let others: Vec<Rect> = solids.iter().filter(|r| **r != own && !walls.contains(r)).cloned().collect();
365	    let _ = other;
366	    if !seg_clear(&others, p, e) || others.iter().any(|r| r.contains_open(e.0, e.1)) {
367	        return None;
368	    }
369	    if !seg_band_ok(bands, p, e) {
370	        return None;
371	    }
372	    Some((p, e))
373	}
