375	// Find the cheapest orthogonal route: cost = length + 2K per bend.
376	pub fn search(env: &Env, req: &PortReq) -> Option<Path> {
377	    let k = env.k;
378	    let solids = env.solids();
379	    let bands = wall_bands(env);
380	    let a = env.a;
381	    let b = env.b;
382	    // grid lines
383	    let mut xs: Vec<f64> = Vec::new();
384	    let mut ys: Vec<f64> = Vec::new();
385	    for r in &solids {
386	        xs.push(r.x0);
387	        xs.push(r.x1);
388	        ys.push(r.y0);
389	        ys.push(r.y1);
390	    }
391	    for o in &env.obs {
392	        if o.kind == ObKind::WallBoth {
393	            let r = o.r;
394	            xs.push(r.x0 - k);
395	            xs.push(r.x0 + k);
396	            xs.push(r.x1 - k);
397	            xs.push(r.x1 + k);
398	            ys.push(r.y0 - k);
399	            ys.push(r.y0 + k);
400	            ys.push(r.y1 - k);
401	            ys.push(r.y1 + k);
402	        }
403	    }
404	    xs.push(a.cx());
405	    xs.push(b.cx());
406	    ys.push(a.cy());
407	    ys.push(b.cy());
408	    for (first, sides) in [(true, req.sides_a), (false, req.sides_b)] {
409	        for &sd in sides {
410	            if let Some((_, e)) = stub(env, &solids, &bands, first, sd) {
411	                xs.push(e.0);
412	                ys.push(e.1);
413	            }
414	        }
415	    }
416	    let xs = uniq(xs);
417	    let ys = uniq(ys);
418	    let nx = xs.len();
419	    let ny = ys.len();
420	    let xi = |x: f64| xs.iter().position(|v| (v - x).abs() < 1e-7);
421	    let yi = |y: f64| ys.iter().position(|v| (v - y).abs() < 1e-7);
422	    let vid = |i: usize, j: usize| j * nx + i;
423	    let nv = nx * ny;
424	    // vertex freedom
425	    let mut free = vec![true; nv];
426	    let mut banded = vec![false; nv];
427	    for j in 0..ny {
428	        for i in 0..nx {
429	            let (x, y) = (xs[i], ys[j]);
430	            if solids.iter().any(|r| r.contains_open(x, y)) {
431	                free[vid(i, j)] = false;
432	            }
433	            if in_band(&bands, x, y) {
434	                banded[vid(i, j)] = true;
435	            }
436	        }
437	    }
438	    // start / end stubs
439	    struct End {
440	        side: Side,
441	        port: (f64, f64),
442	        v: usize,
443	    }
444	    let mut starts: Vec<End> = Vec::new();
445	    for &sd in req.sides_a {
446	        if let Some((p, e)) = stub(env, &solids, &bands, true, sd) {
447	            let (Some(i), Some(j)) = (xi(e.0), yi(e.1)) else { continue };
448	            starts.push(End { side: sd, port: p, v: vid(i, j) });
449	        }
450	    }
451	    let mut ends: Vec<End> = Vec::new();
452	    for &sd in req.sides_b {
453	        if let Some((p, e)) = stub(env, &solids, &bands, false, sd) {
454	            let (Some(i), Some(j)) = (xi(e.0), yi(e.1)) else { continue };
455	            ends.push(End { side: sd, port: p, v: vid(i, j) });
456	        }
457	    }
458	    if starts.is_empty() || ends.is_empty() {
459	        return None;
460	    }
461	    // Dijkstra over (vertex, heading)
462	    let ns = nv * 4;
463	    let mut dist = vec![f64::INFINITY; ns];
464	    let mut prev = vec![usize::MAX; ns];
465	    let mut heap = BinaryHeap::new();
466	    let mut seq: u64 = 0;
467	    for (si, st) in starts.iter().enumerate() {
468	        let s = st.v * 4 + side_dir_idx(st.side);
469	        if k < dist[s] {
470	            dist[s] = k;
471	            prev[s] = usize::MAX - 1 - si;
472	            heap.push(HeapItem { cost: k, seq, state: s });
473	            seq += 1;
474	        }
475	    }
476	    let bend = 2.0 * k;
477	    let mut best: Option<(f64, usize, usize)> = None; // (cost, state, end idx)
478	    while let Some(HeapItem { cost, state, .. }) = heap.pop() {
479	        if cost > dist[state] + 1e-9 {
480	            continue;
481	        }
482	        if let Some((bc, _, _)) = best {
483	            if cost > bc + 1e-9 {
484	                break;
485	            }
486	        }
487	        let v = state / 4;
488	        let d = state % 4;
489	        let i = v % nx;
490	        let j = v / nx;
491	        // reaching an end
492	        for (ei, en) in ends.iter().enumerate() {
493	            if en.v == v {
494	                let need = (side_dir_idx(en.side) + 2) % 4;
495	                let c = cost + k + if d == need { 0.0 } else { bend };
496	                if d == (need + 2) % 4 {
497	                    continue;
498	                }
499	                if best.map_or(true, |(bc, _, _)| c < bc - 1e-9) {
500	                    best = Some((c, state, ei));
501	                }
502	            }
503	        }
504	        // moves
505	        for nd in 0..4 {
506	            if nd == (d + 2) % 4 {
507	                continue;
508	            }
509	            if nd != d && banded[v] {
510	                continue;
511	            }
512	            let (ni, nj) = match nd {
513	                0 => {
514	                    if i + 1 >= nx {
515	                        continue;
516	                    }
517	                    (i + 1, j)
518	                }
519	                1 => {
520	                    if j + 1 >= ny {
521	                        continue;
522	                    }
523	                    (i, j + 1)
524	                }
525	                2 => {
526	                    if i == 0 {
527	                        continue;
528	                    }
529	                    (i - 1, j)
530	                }
531	                _ => {
532	                    if j == 0 {
533	                        continue;
534	                    }
535	                    (i, j - 1)
536	                }
537	            };
538	            let nvx = vid(ni, nj);
539	            if !free[nvx] {
540	                continue;
541	            }
542	            let p = (xs[i], ys[j]);
543	            let q = (xs[ni], ys[nj]);
544	            if !seg_clear(&solids, p, q) || !seg_band_ok(&bands, p, q) {
545	                continue;
546	            }
547	            let fw = free_width(&solids, p, q);
548	            if fw <= 1e-9 || fw < req.need - 1e-9 {
549	                continue;
550	            }
551	            let len = (q.0 - p.0).abs() + (q.1 - p.1).abs();
552	            let nc = cost + len + if nd == d { 0.0 } else { bend };
553	            let ns2 = nvx * 4 + nd;
554	            if nc < dist[ns2] - 1e-9 {
555	                dist[ns2] = nc;
556	                prev[ns2] = state;
557	                heap.push(HeapItem { cost: nc, seq, state: ns2 });
558	                seq += 1;
559	            }
560	        }
561	    }
562	    let (cost, st, ei) = best?;
563	    // rebuild
564	    let mut verts: Vec<(f64, f64)> = Vec::new();
565	    let mut cur = st;
566	    let start_idx;
567	    loop {
568	        let v = cur / 4;
569	        verts.push((xs[v % nx], ys[v / nx]));
570	        let p = prev[cur];
571	        if p >= usize::MAX - 1 - starts.len() && p != usize::MAX {
572	            start_idx = usize::MAX - 1 - p;
573	            break;
574	        }
575	        if p == usize::MAX {
576	            return None;
577	        }
578	        cur = p;
579	    }
580	    verts.reverse();
581	    let mut pts = vec![starts[start_idx].port];
582	    pts.extend(verts);
583	    pts.push(ends[ei].port);
584	    let pts = simplify(&pts);
585	    Some(Path { pts, sa: starts[start_idx].side, sb: ends[ei].side, cost })
586	}
