588	// Drop repeated and collinear interior points.
589	pub fn simplify(pts: &[(f64, f64)]) -> Vec<(f64, f64)> {
590	    let mut o: Vec<(f64, f64)> = Vec::new();
591	    for &p in pts {
592	        if let Some(l) = o.last() {
593	            if (l.0 - p.0).abs() < 1e-9 && (l.1 - p.1).abs() < 1e-9 {
594	                continue;
595	            }
596	        }
597	        o.push(p);
598	    }
599	    let mut i = 1;
600	    while i + 1 < o.len() {
601	        let (a, b, c) = (o[i - 1], o[i], o[i + 1]);
602	        let col = ((a.0 - b.0).abs() < 1e-9 && (b.0 - c.0).abs() < 1e-9) || ((a.1 - b.1).abs() < 1e-9 && (b.1 - c.1).abs() < 1e-9);
603	        if col {
604	            o.remove(i);
605	        } else {
606	            i += 1;
607	        }
608	    }
609	    o
610	}
