616	// The channel a staircase segment slides in: between its neighbours' far
617	// ends and the inflated obstacles overlapping its whole span.
618	pub fn stair_interval(solids: &[Rect], pts: &[(f64, f64)], j: usize) -> (f64, f64) {
619	    let p = pts[j];
620	    let q = pts[j + 1];
621	    let vertical = (p.0 - q.0).abs() < 1e-9;
622	    let pos = if vertical { p.0 } else { p.1 };
623	    let (fa, fb) = if vertical { (pts[j - 1].0, pts[j + 2].0) } else { (pts[j - 1].1, pts[j + 2].1) };
624	    let mut lo = fa.min(fb);
625	    let mut hi = fa.max(fb);
626	    let (s0, s1) = if vertical { (p.1.min(q.1), p.1.max(q.1)) } else { (p.0.min(q.0), p.0.max(q.0)) };
627	    for r in solids {
628	        let (a0, a1, b0, b1) = if vertical { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
629	        if a0 < s1 - EPS && a1 > s0 + EPS {
630	            if b1 <= pos + EPS && b1 > lo {
631	                lo = b1;
632	            }
633	            if b0 >= pos - EPS && b0 < hi {
634	                hi = b0;
635	            }
636	        }
637	    }
638	    (lo, hi)
639	}
