684	pub fn is_u(pts: &[(f64, f64)], j: usize) -> bool {
685	    let d0 = seg_dir(pts[j - 1], pts[j]);
686	    let d2 = seg_dir(pts[j + 1], pts[j + 2]);
687	    d0 == (d2 + 2) % 4
688	}
