690	// Free segments settle in their channel: staircases midway across their
691	// span; U-turns midway when boxed in beside their start, else they keep
692	// hugging what they go around.
693	pub fn centre_staircases(env: &Env, pts: &mut Vec<(f64, f64)>) {
694	    let solids = env.solids();
695	    let n = pts.len();
696	    if n < 4 {
697	        return;
698	    }
699	    for i in 1..n - 2 {
700	        // a simple U between the two end stubs always hugs
701	        if is_u(pts, i) && n == 4 {
702	            continue;
703	        }
704	        let (lo, hi) = if is_u(pts, i) { u_interval(env, &solids, pts, i) } else { stair_interval(&solids, pts, i) };
705	        if !lo.is_finite() || !hi.is_finite() {
706	            continue;
707	        }
708	        let m = (lo + hi) / 2.0;
709	        let vertical = (pts[i].0 - pts[i + 1].0).abs() < 1e-9;
710	        if vertical {
711	            pts[i].0 = m;
712	            pts[i + 1].0 = m;
713	        } else {
714	            pts[i].1 = m;
715	            pts[i + 1].1 = m;
716	        }
717	    }
718	}
