720	// Natural routing: an S-curve between two facing side centres (the
721	// dominant axis between the centres picks the sides).
722	pub fn natural(a: &Rect, b: &Rect, req: &crate::wires::LinkReq) -> (Vec<(f64, f64)>, [(f64, f64); 4], Side, Side) {
723	    let dx = b.cx() - a.cx();
724	    let dy = b.cy() - a.cy();
725	    let (sa, sb) = if dx.abs() >= dy.abs() {
726	        if dx >= 0.0 {
727	            (Side::Right, Side::Left)
728	        } else {
729	            (Side::Left, Side::Right)
730	        }
731	    } else if dy >= 0.0 {
732	        (Side::Bottom, Side::Top)
733	    } else {
734	        (Side::Top, Side::Bottom)
735	    };
736	    let s = side_point(a, sa, 0.0);
737	    let e = side_point(b, sb, 0.0);
738	    let ds = sa.dir();
739	    let de = sb.dir();
740	    let stub_s = if req.mark_len_s > 0.0 { req.mark_len_s } else { 2.0 };
741	    let stub_e = if req.mark_len_e > 0.0 { req.mark_len_e } else { 2.0 };
742	    let s1 = (s.0 + ds.0 * stub_s, s.1 + ds.1 * stub_s);
743	    let e1 = (e.0 + de.0 * stub_e, e.1 + de.1 * stub_e);
744	    let dist = ((e1.0 - s1.0).powi(2) + (e1.1 - s1.1).powi(2)).sqrt();
745	    let along = if sa.horizontal() { (e1.1 - s1.1).abs() } else { (e1.0 - s1.0).abs() };
746	    let h = (dist / 2.0).min(along.max(dist / 4.0));
747	    let c1 = (s1.0 + ds.0 * h, s1.1 + ds.1 * h);
748	    let c2 = (e1.0 + de.0 * h, e1.1 + de.1 * h);
749	    (vec![s, e], [s1, c1, c2, e1], sa, sb)
750	}
