67	fn bundles_of(reqs: &[LinkReq]) -> (Vec<Bundle>, Vec<usize>) {
68	    let mut out: Vec<Bundle> = Vec::new();
69	    let mut of = vec![usize::MAX; reqs.len()];
70	    for (i, r) in reqs.iter().enumerate() {
71	        if r.routing != "orthogonal" || r.from == r.to {
72	            continue;
73	        }
74	        let found = out.iter().position(|b| {
75	            let first = &reqs[b.reqs[0]];
76	            if first.k != r.k {
77	                return false;
78	            }
79	            let ok = |x: Option<Side>, y: Option<Side>| x.is_none() || x == y;
80	            if r.from == b.p && r.to == b.q {
81	                ok(r.anchor_a, b.anchor_p) && ok(r.anchor_b, b.anchor_q)
82	            } else if r.from == b.q && r.to == b.p {
83	                ok(r.anchor_b, b.anchor_p) && ok(r.anchor_a, b.anchor_q)
84	            } else {
85	                false
86	            }
87	        });
88	        match found {
89	            Some(bi) => {
90	                out[bi].reqs.push(i);
91	                of[i] = bi;
92	            }
93	            None => {
94	                of[i] = out.len();
95	                out.push(Bundle { reqs: vec![i], p: r.from, q: r.to, anchor_p: r.anchor_a, anchor_q: r.anchor_b });
96	            }
97	        }
98	    }
99	    (out, of)
100	}
