102	// Extra cost of a detour segment: it is priced at the middle of its channel
103	// (an open side counts K + 20 deep), not at the hugging position.
104	fn detour_penalty(env: &Env, pts: &[(f64, f64)]) -> f64 {
105	    let mut pen = 0.0;
106	    let n = pts.len();
107	    if n < 4 {
108	        return 0.0;
109	    }
110	    for i in 1..n - 2 {
111	        let d0 = seg_dir(pts[i - 1], pts[i]);
112	        let d2 = seg_dir(pts[i + 1], pts[i + 2]);
113	        if d0 != (d2 + 2) % 4 {
114	            continue;
115	        }
116	            pen += channel_depth_ext(env, pts, i, d0);
117	    }
118	    pen
119	}
120	
121	// Depth beyond a U-turn segment; a U whose legs are the end stubs is
122	// measured across both endpoints' clearance boxes.
123	fn channel_depth_ext(env: &Env, pts: &[(f64, f64)], j: usize, d: usize) -> f64 {
124	    let n = pts.len();
125	    let p = pts[j];
126	    let q = pts[j + 1];
127	    let horizontal = (p.1 - q.1).abs() < 1e-9;
128	    let mut lo = if horizontal { p.0.min(q.0) } else { p.1.min(q.1) };
129	    let mut hi = if horizontal { p.0.max(q.0) } else { p.1.max(q.1) };
130	    if j == 1 && j + 2 == n - 1 {
131	        for r in [env.a.grow(env.k), env.b.grow(env.k)] {
132	            let (a0, a1) = if horizontal { (r.x0, r.x1) } else { (r.y0, r.y1) };
133	            lo = lo.min(a0);
134	            hi = hi.max(a1);
135	        }
136	    }
137	    let k = env.k;
138	    let solids = env.solids();
139	    let pos = if horizontal { p.1 } else { p.0 };
140	    let mut far = f64::INFINITY;
141	    for r in &solids {
142	        let (rlo, rhi, near) = if horizontal {
143	            (r.x0, r.x1, if d == 1 { r.y0 - pos } else { pos - r.y1 })
144	        } else {
145	            (r.y0, r.y1, if d == 0 { r.x0 - pos } else { pos - r.x1 })
146	        };
147	        if rlo < hi - EPS && rhi > lo + EPS && near >= -EPS {
148	            far = far.min(near);
149	        }
150	    }
151	    // a container holding both ends bounds the channel at its border
152	    for o in &env.obs {
153	        if o.kind != ObKind::WallBoth {
154	            continue;
155	        }
156	        let r = o.r;
157	        let near = if horizontal {
158	            if d == 1 {
159	                r.y1 - pos
160	            } else {
161	                pos - r.y0
162	            }
163	        } else if d == 0 {
164	            r.x1 - pos
165	        } else {
166	            pos - r.x0
167	        };
168	        if near >= -EPS {
169	            far = far.min(near);
170	        }
171	    }
172	    if far.is_finite() {
173	        far
174	    } else {
175	        k + 20.0
176	    }
177	}
178	
179	// Free depth beyond a segment in direction `d` (towards the open side),
180	// capped at K + 20 when nothing bounds it.
181	fn channel_depth(env: &Env, p: (f64, f64), q: (f64, f64), d: usize) -> f64 {
182	    let k = env.k;
183	    let solids = env.solids();
184	    let horizontal = (p.1 - q.1).abs() < 1e-9;
185	    let (lo, hi) = if horizontal { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
186	    let pos = if horizontal { p.1 } else { p.0 };
187	    let mut far = f64::INFINITY;
188	    for r in &solids {
189	        let (rlo, rhi, near) = if horizontal {
190	            (r.x0, r.x1, if d == 1 { r.y0 - pos } else { pos - r.y1 })
191	        } else {
192	            (r.y0, r.y1, if d == 0 { r.x0 - pos } else { pos - r.x1 })
193	        };
194	        if rlo < hi - EPS && rhi > lo + EPS && near >= -EPS {
195	            far = far.min(near);
196	        }
197	    }
198	    if far.is_finite() {
199	        far
200	    } else {
201	        k + 20.0
202	    }
203	}
