209	// A side can hold `n` ports when they fit at half-clearance pitch.
210	fn side_fits(r: &Rect, s: Side, n: usize, k: f64) -> bool {
211	    if n <= 1 {
212	        return true;
213	    }
214	    side_len(r, s) - 2.0 * k >= (n as f64 - 1.0) * k / 2.0 - 1e-9
215	}
