217	// The overlap of two facing sides' port ranges, if they face each other.
218	fn facing_overlap(a: &Rect, sa: Side, b: &Rect, sb: Side, k: f64) -> Option<(f64, f64)> {
219	    if (sa.idx() + 2) % 4 != sb.idx() {
220	        return None;
221	    }
222	    let (a0, a1) = side_span(a, sa);
223	    let (b0, b1) = side_span(b, sb);
224	    let lo = (a0 + k).max(b0 + k);
225	    let hi = (a1 - k).min(b1 - k);
226	    if lo > hi + 1e-9 {
227	        return None;
228	    }
229	    Some((lo, hi))
230	}
