232	// A U-turn segment already placed in a channel (for capacity checks).
233	#[derive(Clone, Debug)]
234	struct ChanUse {
235	    horiz: bool,
236	    pos: f64,
237	    u: usize,
238	    lo: f64,
239	    hi: f64,
