244	fn seg_span(p: (f64, f64), q: (f64, f64)) -> (bool, f64, f64, f64) {
245	    let horiz = (p.1 - q.1).abs() < 1e-9;
246	    if horiz {
247	        (true, p.1, p.0.min(q.0), p.0.max(q.0))
248	    } else {
249	        (false, p.0, p.1.min(q.1), p.1.max(q.1))
250	    }
251	}
