253	// U-turn segments of a path: (index, outward direction).
254	fn u_segments(pts: &[(f64, f64)]) -> Vec<(usize, usize)> {
255	    let m = pts.len();
256	    let mut v = Vec::new();
257	    if m < 4 {
258	        return v;
259	    }
260	    for j in 1..m - 2 {
261	        let d0 = seg_dir(pts[j - 1], pts[j]);
262	        let d2 = seg_dir(pts[j + 1], pts[j + 2]);
263	        if d0 == (d2 + 2) % 4 {
264	            v.push((j, d0));
265	        }
266	    }
267	    v
268	}
