270	struct Occupancy {
271	    // per (node, side): the port slots taken (a fan's trunk is one slot)
272	    sides: std::collections::HashMap<(usize, usize), Vec<i64>>,
273	    chans: Vec<ChanUse>,
274	}
275	
276	// Slots a side would hold with `new` added.
277	fn slots_with(occ: &Occupancy, node: usize, side: Side, new: &[i64]) -> usize {
278	    let mut v: Vec<i64> = occ.sides.get(&(node, side.idx())).cloned().unwrap_or_default();
279	    for k in new {
280	        if !v.contains(k) {
281	            v.push(*k);
282	        }
283	    }
284	    v.len()
285	}
