287	fn route_bundle(env: &Env, n: usize, b: &Bundle, keys: &(Vec<i64>, Vec<i64>), occ: &Occupancy, force: Option<(usize, Side)>) -> Option<(f64, Path)> {
288	    let mut ap = b.anchor_p;
289	    let mut aq = b.anchor_q;
290	    if let Some((node, side)) = force {
291	        if node == b.p {
292	            if ap.map_or(false, |s| s != side) {
293	                return None;
294	            }
295	            ap = Some(side);
296	        } else {
297	            if aq.map_or(false, |s| s != side) {
298	                return None;
299	            }
300	            aq = Some(side);
301	        }
302	    }
303	    let sas: Vec<Side> = match ap {
304	        Some(s) => vec![s],
305	        None => ORDER.to_vec(),
306	    };
307	    let sbs: Vec<Side> = match aq {
308	        Some(s) => vec![s],
309	        None => ORDER_B.to_vec(),
310	    };
311	    let k = env.k;
312	    let mut best: Option<(f64, Path)> = None;
313	    for &sa in &sas {
314	        for &sb in &sbs {
315	            let need = if n <= 1 { 0.0 } else { (n as f64 - 1.0) * k / 2.0 };
316	            let pr = PortReq { sides_a: &[sa], sides_b: &[sb], need };
317	            let Some(mut p) = search(env, &pr) else { continue };
318	            // sides: a straight bundle needs the shared range, others each
319	            // side (counting the wires already there)
320	            let straight_ok = p.pts.len() <= 4
321	                && facing_overlap(&env.a, sa, &env.b, sb, k).map_or(false, |(lo, hi)| n <= 1 || hi - lo >= (n as f64 - 1.0) * k / 2.0 - 1e-9);
322	            let na = slots_with(occ, b.p, sa, &keys.0);
323	            let nb = slots_with(occ, b.q, sb, &keys.1);
324	            if !straight_ok && !(side_fits(&env.a, sa, na, k) && side_fits(&env.b, sb, nb, k)) {
325	                continue;
326	            }
327	            // channels: U-turns stack in a channel of limited depth
328	            let mut chan_ok = true;
329	            for (j, u) in u_segments(&p.pts) {
330	                let (horiz, pos, lo, hi) = seg_span(p.pts[j], p.pts[j + 1]);
331	                let depth = channel_depth(env, p.pts[j], p.pts[j + 1], u);
332	                let m: usize = occ
333	                    .chans
334	                    .iter()
335	                    .filter(|c| c.horiz == horiz && (c.pos - pos).abs() < 1e-6 && c.u == u && c.lo < hi - EPS && c.hi > lo + EPS)
336	                    .map(|c| c.count)
337	                    .sum();
338	                let tot = m + n;
339	                if tot >= 2 && depth / (tot as f64 - 1.0) < k / 2.0 - 1e-9 {
340	                    chan_ok = false;
341	                }
342	            }
343	            if !chan_ok {
344	                continue;
345	            }
346	            let c = p.cost + detour_penalty(env, &p.pts);
347	            if best.as_ref().map_or(true, |(bc, _)| c < *bc - 1e-9) {
348	                centre_staircases(env, &mut p.pts);
349	                best = Some((c, p));
350	            }
351	        }
352	    }
353	    best
354	}
