356	// A link between a container and something inside it runs straight from
357	// the container's border to the inner node's nearest side.
358	fn parent_child(world: &World, p: usize, q: usize, p_outer: bool) -> Path {
359	    let (outer, inner) = if p_outer { (world.rects[p], world.rects[q]) } else { (world.rects[q], world.rects[p]) };
360	    let gaps = [
361	        (Side::Right, outer.x1 - inner.x1),
362	        (Side::Left, inner.x0 - outer.x0),
363	        (Side::Bottom, outer.y1 - inner.y1),
364	        (Side::Top, inner.y0 - outer.y0),
365	    ];
366	    let mut best = gaps[0];
367	    for g in gaps.iter().skip(1) {
368	        if g.1 < best.1 - 1e-9 {
369	            best = *g;
370	        }
371	    }
372	    let sd = best.0;
373	    let ip = side_point(&inner, sd, 0.0);
374	    let op = match sd {
375	        Side::Right => (outer.x1, ip.1),
376	        Side::Left => (outer.x0, ip.1),
377	        Side::Bottom => (ip.0, outer.y1),
378	        Side::Top => (ip.0, outer.y0),
379	    };
380	    let pts = if p_outer { vec![op, ip] } else { vec![ip, op] };
381	    Path { pts, sa: sd, sb: sd, cost: 0.0 }
382	}
