384	// Corner radii: terminal segments can be used whole (after the marker
385	// pull-back), interior ones are shared by their two corners in proportion
386	// to what they want.
387	fn cap_radii(pts: &[(f64, f64)], want: &[f64], pull_s: f64, pull_e: f64) -> Vec<f64> {
388	    let n = pts.len();
389	    if n < 3 {
390	        return vec![];
391	    }
392	    let seg = |i: usize| ((pts[i + 1].0 - pts[i].0).abs() + (pts[i + 1].1 - pts[i].1).abs());
393	    let share = |len: f64, mine: f64, other: f64| {
394	        if mine + other > len && mine + other > 0.0 {
395	            len * mine / (mine + other)
396	        } else {
397	            mine
398	        }
399	    };
400	    let mut out = Vec::new();
401	    for c in 1..n - 1 {
402	        let r = want[c - 1];
403	        let before = if c == 1 { seg(0) - pull_s } else { share(seg(c - 1), r, want[c - 2]) };
404	        let after = if c == n - 2 { seg(c) - pull_e } else { share(seg(c), r, want[c]) };
405	        out.push(r.min(before).min(after).max(0.0));
406	    }
407	    out
408	}
