414	// One wire being planned.
415	#[derive(Clone, Debug)]
416	struct W {
417	    req: usize,
418	    bundle: usize,
419	    slot: usize,
420	    // polyline from the (promoted) start node to the end node
421	    pts: Vec<(f64, f64)>,
