428	    offs: Vec<f64>,
429	    straight: bool,
430	    // fan groups sharing a trunk port at the start / end node
431	    fan_s: Option<usize>,
432	    fan_e: Option<usize>,
433	    // a container-to-inner link takes its line from the inner node's side
434	    inner_end: Option<usize>,
435	    // a straight wire's preferred line: halfway between the two centres,
436	    // kept inside the range both sides can take
437	    ideal: Option<f64>,
438	}
