440	pub fn route_links(ctx: &Ctx, world: &World, reqs: &[LinkReq]) -> Vec<Routed> {
441	    let mut out: Vec<Option<Routed>> = (0..reqs.len()).map(|_| None).collect();
442	    // natural and straight routing need no planning
443	    for (i, req) in reqs.iter().enumerate() {
444	        let a = world.rects[req.from];
445	        let b = world.rects[req.to];
446	        if req.routing == "straight" {
447	            let (p, q) = crate::links::stray_line(&a, &b);
448	            out[i] = Some(Routed { stray: false, pts: vec![p, q], radii: vec![], curve: None, sa: None, sb: None });
449	        } else if req.routing == "natural" {
450	            let (pts, curve, sa, sb) = natural(&a, &b, req);
451	            out[i] = Some(Routed { stray: false, pts, radii: vec![], curve: Some(curve), sa: Some(sa), sb: Some(sb) });
452	        } else if req.from == req.to {
453	            let k = req.k;
454	            let pts = vec![(a.x1, a.cy()), (a.x1 + k, a.cy()), (a.x1 + k, a.y0 - k), (a.cx(), a.y0 - k), (a.cx(), a.y0)];
455	            let want = vec![req.radius; 3];
456	            let radii = cap_radii(&pts, &want, req.pull_s, req.pull_e);
457	            out[i] = Some(Routed { stray: false, pts, radii, curve: None, sa: Some(Side::Right), sb: Some(Side::Top) });
458	        }
459	    }
460	    let (bundles, of) = bundles_of(reqs);
461	    // fans: links of one statement sharing a start (or an end) node
462	    let mut fan_groups: Vec<(usize, Vec<usize>)> = Vec::new(); // (shared node, reqs)
463	    let mut fan_of_start: Vec<Option<usize>> = vec![None; reqs.len()];
464	    let mut fan_of_end: Vec<Option<usize>> = vec![None; reqs.len()];
465	    {
466	        let mut outs: std::collections::BTreeMap<(usize, usize), Vec<usize>> = std::collections::BTreeMap::new();
467	        let mut ins: std::collections::BTreeMap<(usize, usize), Vec<usize>> = std::collections::BTreeMap::new();
468	        for (i, r) in reqs.iter().enumerate() {
469	            if of[i] == usize::MAX {
470	                continue;
471	            }
472	            outs.entry((r.stmt, r.from)).or_default().push(i);
473	            ins.entry((r.stmt, r.to)).or_default().push(i);
474	        }
475	        let mut groups: Vec<(usize, usize, Vec<usize>, bool)> = Vec::new();
476	        for ((_, node), v) in outs {
477	            if v.len() >= 2 {
478	                groups.push((v[0], node, v, true));
479	            }
480	        }
481	        for ((_, node), v) in ins {
482	            if v.len() >= 2 {
483	                groups.push((v[0], node, v, false));
484	            }
485	        }
486	        groups.sort_by_key(|g| g.0);
487	        for (_, node, v, is_out) in groups {
488	            let gi = fan_groups.len();
489	            for &ri in &v {
490	                if is_out {
491	                    if fan_of_start[ri].is_none() {
492	                        fan_of_start[ri] = Some(gi);
493	                    }
494	                } else if fan_of_end[ri].is_none() {
495	                    fan_of_end[ri] = Some(gi);
496	                }
497	            }
498	            fan_groups.push((node, v));
499	        }
500	    }
501	    let mut occ = Occupancy { sides: std::collections::HashMap::new(), chans: Vec::new() };
502	    // each bundle's port slot keys at its two nodes
503	    let slot_key = |ri: usize, node: usize| -> i64 {
504	        let g = if reqs[ri].from == node { fan_of_start[ri] } else { fan_of_end[ri] };
505	        match g {
506	            Some(gi) if fan_groups[gi].0 == node => gi as i64,
507	            _ => -(ri as i64) - 1,
508	        }
509	    };
510	    let keys: Vec<(Vec<i64>, Vec<i64>)> = bundles.iter().map(|b| (b.reqs.iter().map(|&ri| slot_key(ri, b.p)).collect(), b.reqs.iter().map(|&ri| slot_key(ri, b.q)).collect())).collect();
511	    let mut wires: Vec<W> = Vec::new();
512	    let envs: Vec<Env> = bundles.iter().map(|b| env_for(ctx, world, b.p, b.q, reqs[b.reqs[0]].k)).collect();
513	    let mut done = vec![false; bundles.len()];
514	    for bi in 0..bundles.len() {
515	        if done[bi] {
516	            continue;
517	        }
518	        // a fresh fan routes jointly: every member leaves the shared node
519	        // through the same side, the cheapest such side overall
520	        let first = bundles[bi].reqs[0];
521	        // the first fan (out, then in) whose member bundles are all fresh
522	        let fresh = |gi: usize, done: &Vec<bool>| -> bool {
523	            let (_, members) = &fan_groups[gi];
524	            let mut mbs: Vec<usize> = Vec::new();
525	            for &ri in members {
526	                if !mbs.contains(&of[ri]) {
527	                    mbs.push(of[ri]);
528	                }
529	            }
530	            mbs.len() >= 2 && mbs.iter().all(|&mb| !done[mb])
531	        };
532	        let fan = [fan_of_start[first], fan_of_end[first]].into_iter().flatten().find(|&gi| fresh(gi, &done));
533	        let mut joint: Option<Vec<(usize, Path)>> = None;
534	        if let Some(gi) = fan {
535	            let (node, members) = &fan_groups[gi];
536	            let mut mbs: Vec<usize> = Vec::new();
537	            for &ri in members {
538	                if !mbs.contains(&of[ri]) {
539	                    mbs.push(of[ri]);
540	                }
541	            }
542	            {
543	                let mut best: Option<(f64, Vec<(usize, Path)>)> = None;
544	                for &sd in ORDER.iter() {
545	                    let mut total = 0.0;
546	                    let mut got: Vec<(usize, Path)> = Vec::new();
547	                    let mut ok = true;
548	                    for &mb in &mbs {
549	                        match route_bundle(&envs[mb], bundles[mb].reqs.len(), &bundles[mb], &keys[mb], &occ, Some((*node, sd))) {
550	                            Some((c, p)) => {
551	                                total += c;
552	                                got.push((mb, p));
553	                            }
554	                            None => {
555	                                ok = false;
556	                                break;
557	                            }
558	                        }
559	                    }
560	                    if ok && best.as_ref().map_or(true, |(bc, _)| total < *bc - 1e-9) {
561	                        best = Some((total, got));
562	                    }
563	                }
564	                joint = best.map(|b| b.1);
565	            }
566	        }
567	        let plan: Vec<(usize, Option<Path>)> = match joint {
568	            Some(v) => v.into_iter().map(|(mb, p)| (mb, Some(p))).collect(),
569	            None => {
570	                let b = &bundles[bi];
571	                let nested = crate::links::is_ancestor(ctx, b.p, b.q) || crate::links::is_ancestor(ctx, b.q, b.p);
572	                if nested {
573	                    vec![(bi, Some(parent_child(world, b.p, b.q, crate::links::is_ancestor(ctx, b.p, b.q))))]
574	                } else {
575	                    vec![(bi, route_bundle(&envs[bi], bundles[bi].reqs.len(), &bundles[bi], &keys[bi], &occ, None).map(|x| x.1))]
576	                }
577	            }
578	        };
579	        for (mb, path) in plan {
580	            done[mb] = true;
581	            let b = &bundles[mb];
582	            let env = &envs[mb];
583	            let k = env.k;
584	            let n = b.reqs.len();
585	            let Some(path) = path else {
586	                for &ri in &b.reqs {
587	                    out[ri] = Some(stray());
588	                }
589	                continue;
590	            };
591	            for (node, side, ks) in [(b.p, path.sa, &keys[mb].0), (b.q, path.sb, &keys[mb].1)] {
592	                let v = occ.sides.entry((node, side.idx())).or_default();
593	                for k in ks.iter() {
594	                    if !v.contains(k) {
595	                        v.push(*k);
596	                    }
597	                }
598	            }
599	            for (j, u) in u_segments(&path.pts) {
600	                let (horiz, pos, lo, hi) = seg_span(path.pts[j], path.pts[j + 1]);
601	                let depth = channel_depth(env, path.pts[j], path.pts[j + 1], u);
602	                occ.chans.push(ChanUse { horiz, pos, u, lo, hi, depth, count: n });
603	            }
604	            let facing = facing_overlap(&env.a, path.sa, &env.b, path.sb, k);
605	            let z_straight = path.pts.len() <= 4 && facing.map_or(false, |(lo, hi)| n <= 1 || hi - lo >= (n as f64 - 1.0) * k / 2.0 - 1e-9);
606	            let straight = (path.pts.len() == 2 && path.sa == path.sb) || z_straight;
607	            let ideal = if z_straight && !(path.pts.len() == 2 && path.sa == path.sb) {
608	                let (lo, hi) = facing.unwrap();
609	                let mid = if path.sa.horizontal() { (env.a.cx() + env.b.cx()) / 2.0 } else { (env.a.cy() + env.b.cy()) / 2.0 };
610	                Some(mid.max(lo).min(hi))
611	            } else {
612	                None
613	            };
614	            // bundle order: forward links in order, then backward ones reversed
615	            let mut order: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from == b.p).collect();
616	            let mut back: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from != b.p).collect();
617	            back.reverse();
618	            order.extend(back);
619	            for (slot, &ri) in order.iter().enumerate() {
620	                let pts = path.pts.clone();
621	                let m = pts.len();
622	                // fan groups seen from the bundle's orientation
623	                let (fs, fe) = if reqs[ri].from == b.p { (fan_of_start[ri], fan_of_end[ri]) } else { (fan_of_end[ri], fan_of_start[ri]) };
624	                let inner_end = if crate::links::is_ancestor(ctx, b.p, b.q) {
625	                    Some(1)
626	                } else if crate::links::is_ancestor(ctx, b.q, b.p) {
627	                    Some(0)
628	                } else {
629	                    None
630	                };
631	                wires.push(W { req: ri, bundle: mb, slot, pts, sa: path.sa, sb: path.sb, from: b.p, to: b.q, k, offs: vec![0.0; m - 1], straight, fan_s: fs, fan_e: fe, inner_end, ideal });
632	            }
633	        }
634	    }
635	    plan_ports(ctx, world, &bundles, &mut wires);
636	    plan_tracks(&envs, &mut wires);
637	    // nested corners: a corner wrapped round a parallel inner corner takes
638	    // the inner radius plus half the offsets between them
639	    let nests = nest_corners(&wires);
640	    let cross_caps = crossing_caps(&wires);
641	    // a nested corner grows from what the corner just inside it wants,
642	    // once that is held to its end legs and to crossing wires (sharing an
643	    // inner leg with a neighbour corner does not carry over)
644	    let mut eff: Vec<Vec<f64>> = wires.iter().map(|wr| vec![reqs[wr.req].radius; wr.pts.len().saturating_sub(2)]).collect();
645	    let wants_of = |w: usize, eff: &Vec<Vec<f64>>| -> Vec<f64> {
646	        let req = &reqs[wires[w].req];
647	        nests[w]
648	            .iter()
649	            .map(|&(extra, inner)| match inner {
650	                Some((xw, xc)) => eff[xw][xc] + extra,
651	                None => req.radius,
652	            })
653	            .collect()
654	    };
655	    for _ in 0..8 {
656	        let mut changed = false;
657	        for w in 0..wires.len() {
658	            let pts = &wires[w].pts;
659	            let m = pts.len();
660	            if m < 3 {
661	                continue;
662	            }
663	            let seg = |i: usize| ((pts[i + 1].0 - pts[i].0).abs() + (pts[i + 1].1 - pts[i].1).abs());
664	            let want = wants_of(w, &eff);
665	            for c in 0..m - 2 {
666	                let mut v = want[c].min(cross_caps[w][c]);
667	                if c == 0 {
668	                    v = v.min(seg(0));
669	                }
670	                if c == m - 3 {
671	                    v = v.min(seg(m - 2));
672	                }
673	                if (v - eff[w][c]).abs() > 1e-12 {
674	                    eff[w][c] = v;
675	                    changed = true;
676	                }
677	            }
678	        }
679	        if !changed {
680	            break;
681	        }
682	    }
683	    let radii_of = |w: usize| -> Vec<f64> {
684	        let wr = &wires[w];
685	        let req = &reqs[wr.req];
686	        let pts = &wr.pts;
687	        let want = wants_of(w, &eff);
688	        // pull-backs in this wire's own orientation
689	        let (ps, pe) = if req.from == wr.from { (req.pull_s, req.pull_e) } else { (req.pull_e, req.pull_s) };
690	        let m = pts.len();
691	        let seg = |i: usize| ((pts[i + 1].0 - pts[i].0).abs() + (pts[i + 1].1 - pts[i].1).abs());
692	        let pull_e = if m >= 2 && pe > seg(m - 2) + 1e-9 { 0.0 } else { pe };
693	        let pull_s = if m >= 2 && ps > seg(0) + 1e-9 { 0.0 } else { ps };
694	        let mut radii = cap_radii(pts, &want, pull_s, pull_e);
695	        // an arc never sweeps over a crossing wire
696	        for (r, c) in radii.iter_mut().zip(cross_caps[w].iter()) {
697	            if *r > *c {
698	                *r = *c;
699	            }
700	        }
701	        radii
702	    };
703	    for (w, wr) in wires.iter().enumerate() {
704	        let req = &reqs[wr.req];
705	        let mut pts = wr.pts.clone();
706	        let mut radii = if wr.straight { vec![] } else { radii_of(w) };
707	        let (mut sa, mut sb) = (wr.sa, wr.sb);
708	        if req.from != wr.from {
709	            pts.reverse();
710	            radii.reverse();
711	            std::mem::swap(&mut sa, &mut sb);
712	        }
713	        out[wr.req] = Some(Routed { stray: false, pts, radii, curve: None, sa: Some(sa), sb: Some(sb) });
714	    }
715	    out.into_iter().map(|o| o.unwrap_or_else(stray)).collect()
716	}
