718	// Per corner, the distance to the nearest point where another wire
719	// crosses one of its two legs (infinite when none).
720	fn crossing_caps(wires: &[W]) -> Vec<Vec<f64>> {
721	    let mut segs: Vec<(usize, (f64, f64), (f64, f64))> = Vec::new();
722	    for (wi, w) in wires.iter().enumerate() {
723	        for k in 0..w.pts.len().saturating_sub(1) {
724	            segs.push((wi, w.pts[k], w.pts[k + 1]));
725	        }
726	    }
727	    // the crossing point of two perpendicular segments, strictly inside both
728	    let cross = |p: (f64, f64), q: (f64, f64), a: (f64, f64), b: (f64, f64)| -> Option<(f64, f64)> {
729	        let ph = (p.1 - q.1).abs() < 1e-9;
730	        let ah = (a.1 - b.1).abs() < 1e-9;
731	        if ph == ah {
732	            return None;
733	        }
734	        let (h0, h1, v0, v1) = if ph { (p, q, a, b) } else { (a, b, p, q) };
735	        let x = v0.0;
736	        let y = h0.1;
737	        let inside_h = x > h0.0.min(h1.0) + 1e-9 && x < h0.0.max(h1.0) - 1e-9;
738	        let inside_v = y > v0.1.min(v1.1) + 1e-9 && y < v0.1.max(v1.1) - 1e-9;
739	        if inside_h && inside_v {
740	            Some((x, y))
741	        } else {
742	            None
743	        }
744	    };
745	    wires
746	        .iter()
747	        .enumerate()
748	        .map(|(wi, w)| {
749	            let n = w.pts.len();
750	            let mut caps = vec![f64::INFINITY; n.saturating_sub(2)];
751	            if n < 3 || w.straight {
752	                return caps;
753	            }
754	            for c in 1..n - 1 {
755	                let corner = w.pts[c];
756	                for (p, q) in [(w.pts[c - 1], w.pts[c]), (w.pts[c], w.pts[c + 1])] {
757	                    for &(oi, a, b) in &segs {
758	                        if oi == wi {
759	                            continue;
760	                        }
761	                        if let Some(x) = cross(p, q, a, b) {
762	                            let d = (x.0 - corner.0).abs() + (x.1 - corner.1).abs();
763	                            if d < caps[c - 1] {
764	                                caps[c - 1] = d;
765	                            }
766	                        }
767	                    }
768	                }
769	            }
770	            caps
771	        })
772	        .collect()
773	}
