775	// Extra radius per corner (added to the base radius). Corners turning the
776	// same way whose wires run side by side nest: the inner one keeps the base
777	// radius, outer ones grow by half their offsets so the arcs stay parallel.
778	fn nest_corners(wires: &[W]) -> Vec<Vec<(f64, Option<(usize, usize)>)>> {
779	    struct C {
780	        w: usize,
781	        c: usize,
782	        u: usize,
783	        v: usize,
784	        p: (f64, f64),
785	        a: (f64, f64),
786	        b: (f64, f64),
787	    }
788	    let mut cs: Vec<C> = Vec::new();
789	    for (wi, w) in wires.iter().enumerate() {
790	        if w.straight || w.pts.len() < 3 {
791	            continue;
792	        }
793	        for c in 1..w.pts.len() - 1 {
794	            let u = seg_dir(w.pts[c - 1], w.pts[c]);
795	            let v = seg_dir(w.pts[c], w.pts[c + 1]);
796	            cs.push(C { w: wi, c, u, v, p: w.pts[c], a: w.pts[c - 1], b: w.pts[c + 1] });
797	        }
798	    }
799	    let span_overlap = |a0: f64, a1: f64, b0: f64, b1: f64| a0.min(a1) < b0.max(b1) - 1e-9 && b0.min(b1) < a0.max(a1) - 1e-9;
800	    // is corner y wrapped round corner x (same turn, outside it, side by side)?
801	    let outside = |x: &C, y: &C| -> bool {
802	        if x.u != y.u || x.v != y.v {
803	            return false;
804	        }
805	        let uv = dvec(x.u);
806	        let vv = dvec(x.v);
807	        let d = (y.p.0 - x.p.0, y.p.1 - x.p.1);
808	        let du = d.0 * uv.0 + d.1 * uv.1;
809	        let dv = d.0 * vv.0 + d.1 * vv.1;
810	        // strictly outside on both axes (a trunk sibling sharing the leg is not)
811	        if du < 1e-9 || dv > -1e-9 {
812	            return false;
813	        }
814	        // neighbours only: a few tracks apart at most
815	        let k = wires[x.w].k;
816	        if du > 4.0 * k + 1e-9 || -dv > 4.0 * k + 1e-9 {
817	            return false;
818	        }
819	        // the legs run side by side
820	        let horiz_in = uv.1.abs() < 0.5;
821	        let (in_ok, out_ok) = if horiz_in {
822	            (span_overlap(x.a.0, x.p.0, y.a.0, y.p.0), span_overlap(x.p.1, x.b.1, y.p.1, y.b.1))
823	        } else {
824	            (span_overlap(x.a.1, x.p.1, y.a.1, y.p.1), span_overlap(x.p.0, x.b.0, y.p.0, y.b.0))
825	        };
826	        in_ok && out_ok
827	    };
828	    let mut wants: Vec<Vec<(f64, Option<(usize, usize)>)>> = wires.iter().map(|w| vec![(0.0, None); w.pts.len().saturating_sub(2)]).collect();
829	    for y in 0..cs.len() {
830	        // innermost corner of y's nest: wrapped by y, wrapping nothing
831	        let mut inner: Option<usize> = None;
832	        for x in 0..cs.len() {
833	            if x == y || !outside(&cs[x], &cs[y]) {
834	                continue;
835	            }
836	            inner = Some(match inner {
837	                None => x,
838	                Some(prev) => {
839	                    // the nearest such corner
840	                    let dp = (cs[prev].p.0 - cs[y].p.0).abs() + (cs[prev].p.1 - cs[y].p.1).abs();
841	                    let dx = (cs[x].p.0 - cs[y].p.0).abs() + (cs[x].p.1 - cs[y].p.1).abs();
842	                    if dx < dp {
843	                        x
844	                    } else {
845	                        prev
846	                    }
847	                }
848	            });
849	        }
850	        let Some(x) = inner else { continue };
851	        let (cy, cx) = (&cs[y], &cs[x]);
852	        let extra = if wires[cy.w].bundle == wires[cx.w].bundle {
853	            // within a bundle the offsets are exact multiples of the pitches
854	            let (wy, wx) = (&wires[cy.w], &wires[cx.w]);
855	            ((wy.offs[cy.c - 1] - wx.offs[cx.c - 1]).abs() + (wy.offs[cy.c] - wx.offs[cx.c]).abs()) / 2.0
856	        } else {
857	            ((cy.p.0 - cx.p.0).abs() + (cy.p.1 - cx.p.1).abs()) / 2.0
858	        };
859	        wants[cy.w][cy.c - 1] = (extra, Some((cx.w, cx.c - 1)));
860	    }
861	    wants
862	}
