864	// Where the wire end at `end` (0 start, 1 finish) leaves its side: the
865	// turn class relative to the side's clockwise tangent and the distance to
866	// the first turn.
867	fn end_shape(w: &W, end: usize) -> (i32, f64) {
868	    let pts: Vec<(f64, f64)> = if end == 0 { w.pts.clone() } else { w.pts.iter().rev().cloned().collect() };
869	    let side = if end == 0 { w.sa } else { w.sb };
870	    if pts.len() <= 2 || w.straight {
871	        return (0, 0.0);
872	    }
873	    let t = tangent(side);
874	    let nd = dvec(seg_dir(pts[1], pts[2]));
875	    let dot = nd.0 * t.0 + nd.1 * t.1;
876	    let cls = if dot > 0.5 {
877	        1
878	    } else if dot < -0.5 {
879	        -1
880	    } else {
881	        0
882	    };
883	    let dist = (pts[1].0 - pts[0].0).abs() + (pts[1].1 - pts[0].1).abs();
884	    (cls, dist)
885	}
