887	// The span key (far end, then near end reversed) of the U-turn track a
888	// wire end turns into, if any: smaller is further inside.
889	fn u_key(w: &W, end: usize) -> Option<(f64, f64)> {
890	    let m = w.pts.len();
891	    if w.straight || m < 4 {
892	        return None;
893	    }
894	    let j = if end == 0 { 1 } else { m - 3 };
895	    if !is_u(&w.pts, j) {
896	        return None;
897	    }
898	    let (_, _, lo, hi) = seg_span(w.pts[j], w.pts[j + 1]);
899	    Some((hi, lo))
900	}
