902	// Spread every side's wire ends: ordered so wires do not cross, centred,
903	// pitch the clearance (squeezed down to fit the side).
904	fn plan_ports(ctx: &Ctx, world: &World, bundles: &[Bundle], wires: &mut [W]) {
905	    use std::collections::BTreeMap;
906	    // a straight wire leaving a container takes its port among the ends on
907	    // the side of the child it lines up with
908	    let port_node = |node: usize, side: Side, w: &W| -> usize {
909	        let Some(id) = w.ideal else { return node };
910	        for &c in &ctx.nodes[node].children {
911	            if !crate::links::is_obstacle_kind(ctx, c) || ctx.nodes[c].is("caption") {
912	                continue;
913	            }
914	            let (c0, c1) = side_span(&world.rects[c], side);
915	            if id >= c0 + w.k - 1e-9 && id <= c1 - w.k + 1e-9 {
916	                return c;
917	            }
918	        }
919	        node
920	    };
921	    let mut sides: BTreeMap<(usize, usize), Vec<(usize, usize)>> = BTreeMap::new();
922	    for (wi, w) in wires.iter().enumerate() {
923	        sides.entry((w.from, w.sa.idx())).or_default().push((wi, 0));
924	        sides.entry((w.to, w.sb.idx())).or_default().push((wi, 1));
925	    }
926	    // (only when that child's side has ends of its own)
927	    let mut moves: Vec<((usize, usize), (usize, usize), (usize, usize))> = Vec::new();
928	    for (wi, w) in wires.iter().enumerate() {
929	        for (e, node, side) in [(0, w.from, w.sa), (1, w.to, w.sb)] {
930	            let c = port_node(node, side, w);
931	            if c != node && sides.get(&(c, side.idx())).map_or(false, |v| !v.is_empty()) {
932	                moves.push(((node, side.idx()), (c, side.idx()), (wi, e)));
933	            }
934	        }
935	    }
936	    for (from_key, to_key, end) in moves {
937	        if let Some(v) = sides.get_mut(&from_key) {
938	            v.retain(|x| *x != end);
939	        }
940	        sides.entry(to_key).or_default().push(end);
941	    }
942	    sides.retain(|_, v| !v.is_empty());
943	    // straight wires keep one position on both sides: the busier side decides
944	    let mut straight_pos: std::collections::HashMap<usize, f64> = std::collections::HashMap::new();
945	    let mut entries: Vec<((usize, usize), Vec<(usize, usize)>)> = sides.into_iter().collect();
946	    // busier sides first so straight wires take their positions there; an
947	    // inner node's side goes before its container's
948	    let inner_side = |ends: &Vec<(usize, usize)>| ends.iter().any(|&(wi, e)| wires[wi].inner_end == Some(e));
949	    entries.sort_by(|a, b| inner_side(&b.1).cmp(&inner_side(&a.1)).then(b.1.len().cmp(&a.1.len())).then(a.0.cmp(&b.0)));
950	    for ((node, sidx), mut ends) in entries {
951	        let side = [Side::Top, Side::Right, Side::Bottom, Side::Left][sidx];
952	        let r = world.rects[node];
953	        let k = wires[ends[0].0].k;
954	        // fan members sharing this node and side travel as one trunk port
955	        let fan_key = |w: &W, e: usize| if e == 0 { w.fan_s } else { w.fan_e };
956	        // ends wanting a line of their own come in its order along the side
957	        let tg = tangent(side);
958	        let tsg = if side.horizontal() { tg.0 } else { tg.1 };
