1101	fn apply_port(w: &mut W, end: usize, t: (f64, f64), off: f64, pos: f64) {
1102	    let m = w.pts.len();
1103	    let along_x = t.0.abs() > 0.5;
1104	    if w.straight {
1105	        // the whole line moves; it stays straight (a 2-point line between
1106	        // facing sides)
1107	        let s = w.pts[0];
1108	        let e = w.pts[m - 1];
1109	        let _ = end;
1110	        let (sp, ep) = if along_x { ((pos, s.1), (pos, e.1)) } else { ((s.0, pos), (e.0, pos)) };
1111	        w.pts = vec![sp, ep];
1112	        w.offs = vec![off];
1113	        return;
1114	    }
1115	    let (a, b) = if end == 0 { (0, 1) } else { (m - 1, m - 2) };
1116	    for q in [a, b] {
1117	        if along_x {
1118	            w.pts[q].0 = pos;
1119	        } else {
1120	            w.pts[q].1 = pos;
1121	        }
1122	    }
1123	    if end == 0 {
1124	        w.offs[0] = off;
1125	    } else {
1126	        w.offs[m - 2] = -off;
1127	    }
