// The realistic scene — a mid-size diagram with groups, exercising every
// common routing pattern at once.

{
  gap: 40; clearance: 12;
  |group| { direction: column; }
  // the scene runs left to right; each room stacks its treats
  .loud { stroke: --red; }
  .quiet { stroke: --blue; }
  .happy { stroke: --green; }
  |treat::box| { radius: 6; }
}

|oval#cat| "Cat"

|group#kitchen| [
  |caption| "Kitchen"
  |treat#bowl| "Bowl"
  |treat#water| "Water"
]

|group#garden| [
  |caption| "Garden"
  |treat#dog| "Dog"
  |treat#bird| "Bird"
]

|treat#roof| [
  "Roof"
  |badge| "new"
]

cat -> kitchen.bowl & kitchen.water .loud
cat -> roof .loud

kitchen.bowl -> garden.dog "X" .loud { along: 0.35; }
kitchen.bowl -> garden.dog .loud

kitchen.water <--- garden.dog .quiet
kitchen.water <- garden.dog .quiet
kitchen.water <- garden.dog .quiet

garden.bird -> roof
garden.bird -> roof
kitchen.water <-> garden.bird .quiet
kitchen.water -> roof .happy
kitchen.water -> roof .happy

garden ~> kitchen.bowl .loud

// Small shared helpers: number formatting, escaping, hashing.

// Numbers print with at most four decimals, trailing zeros trimmed.
pub fn f4(v: f64) -> String {
    let mut s = format!("{:.4}", v);
    if s.contains('.') {
        while s.ends_with('0') {
            s.pop();
        }
        if s.ends_with('.') {
            s.pop();
        }
    }
    if s == "-0" {
        s = "0".to_string();
    }
    s
}

// Rust's default float Display (shortest round-trip), used by a few raw paths.
pub fn fraw(v: f64) -> String {
    if v == 0.0 {
        return "0".to_string();
    }
    format!("{}", v)
}

pub fn xml_escape(s: &str) -> String {
    let mut o = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => o.push_str("&amp;"),
            '<' => o.push_str("&lt;"),
            '>' => o.push_str("&gt;"),
            '"' => o.push_str("&quot;"),
            '\'' => o.push_str("&apos;"),
            _ => o.push(c),
        }
    }
    o
}

pub fn fnv1a64(data: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &b in data {
        h ^= b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

pub fn fold32(h: u64) -> u32 {
    ((h >> 32) as u32) ^ (h as u32)
}

pub fn hash8(s: &str) -> String {
    format!("{:08x}", fold32(fnv1a64(s.as_bytes())))
}

