import subprocess, sys, os, re, tempfile, hashlib, pickle, difflib
from concurrent.futures import ThreadPoolExecutor
MINE = '/tmp/bin-link2/executable'
ORIG = '/workspace/executable'
CACHE = '/tmp/link2/cache'
os.makedirs(CACHE, exist_ok=True)
args = sys.argv[1:]
verbose = False
listing = False
files = []
i = 0
while i < len(args):
    a = args[i]
    if a == '-v':
        verbose = True
    elif a == '-l':
        listing = True
    elif a == '-b':
        MINE = args[i + 1]; i += 1
    else:
        files.append(a)
    i += 1


def run(b, src):
    d = tempfile.mkdtemp(prefix='/tmp/link2/rr.')
    p = d + '/r_in.lini'
    open(p, 'w').write(src)
    try:
        r = subprocess.run([b, 'r_in.lini'], capture_output=True, cwd=d, timeout=60)
        res = (r.stdout, r.stderr, r.returncode)
    except subprocess.TimeoutExpired:
        res = (b'TIMEOUT', b'', -1)
    os.remove(p)
    os.rmdir(d)
    return res


def orig(src):
    h = hashlib.sha1(src.encode()).hexdigest()
    cp = CACHE + '/' + h
    if os.path.exists(cp):
        try:
            return pickle.load(open(cp, 'rb'))
        except Exception:
            pass
    r = run(ORIG, src)
    pickle.dump(r, open(cp, 'wb'))
    return r


def strip_ids(b):
    return re.sub(rb'lini-label-cut-[0-9a-f]{8}', b'lini-label-cut-X', re.sub(rb'lini-scope-[0-9a-f]{8}', b'lini-scope-X', b))


def cats(a, b):
    k = set()
    if a[1] != b[1]:
        k.add('stderr')
    x = strip_ids(a[0]).decode(errors='replace').split('\n')
    y = strip_ids(b[0]).decode(errors='replace').split('\n')
    if x == y and a[0] != b[0]:
        k.add('ids')
    for l in difflib.unified_diff(x, y, lineterm='', n=0):
        if l.startswith(('---', '+++', '@@')):
            continue
        if '<path' in l:
            k.add('path')
        elif 'viewBox' in l:
            k.add('viewbox')
        elif 'lini-link-label' in l:
            k.add('label')
        elif 'marker' in l:
            k.add('marker')
        elif 'mask' in l:
            k.add('mask')
        else:
            k.add('other')
    return sorted(k)


def one(s):
    a = orig(s)
    b = run(MINE, s)
    if a == b:
        return ('=', None)
    if strip_ids(a[0]) == strip_ids(b[0]) and a[1:] == b[1:]:
        return ('m', cats(a, b))
    return ('x', cats(a, b))


tot = 0
same = 0
same_nm = 0
allfails = []
with ThreadPoolExecutor(max_workers=16) as ex:
    for f in files:
        snips = [s for s in open(f).read().split('\n----\n') if s.strip()]
        res = list(ex.map(one, snips))
        line = ''.join(r[0] for r in res)
        tot += len(res)
        same += line.count('=')
        same_nm += line.count('=') + line.count('m')
        print('%-24s %4d/%4d  %s' % (os.path.basename(f), line.count('='), len(res), line if len(line) <= 120 else line[:120] + '...'))
        for idx, r in enumerate(res):
            if r[0] != '=':
                allfails.append((f, idx, r, snips[idx]))
print('TOTAL exact %d / %d   (ignoring mask/scope ids: %d)' % (same, tot, same_nm))
if verbose or listing:
    for f, idx, r, s in allfails:
        print('--- %s #%d %s %s' % (os.path.basename(f), idx, r[0], r[1]))
        if listing:
            print(s.strip())

#!/usr/bin/env python3
# usage: gen.py FAMILY SEED N OUT
import random, sys

fam = sys.argv[1]
seed = int(sys.argv[2])
N = int(sys.argv[3])
out_path = sys.argv[4]
R = random.Random(seed * 1000 + hash(fam) % 1000)
names = list('abcdefghijklmnop')
words = ['api', 'db', 'cache', 'queue', 'web', 'auth', 'svc', 'store', 'log', 'user', 'Gateway', 'x', 'Worker pool']
ops_simple = ['->', '->', '->', '<-', '<->', '--', '-->']
ops_all = ['->', '->', '->', '<-', '<->', '--', '-->', '--->', '*->', '-o<', '>-<', '~>', '-*']
labels = ['x', 'yes', 'calls', 'reads', 'flow', 'writes to', 'ok']


def node(i, sizes=False, kinds=False):
    w = R.choice(words)
    t = 'box'
    if kinds and R.random() < 0.25:
        t = R.choice(['oval', 'cyl', 'diamond', 'circle'])
    extra = ''
    if sizes:
        decl = []
        if R.random() < 0.35:
            decl.append('width: %d' % R.choice([40, 60, 80, 100, 120, 160, 200]))
        if R.random() < 0.35:
            decl.append('height: %d' % R.choice([30, 40, 60, 80, 100, 140]))
        if decl:
            extra = ' { %s }' % '; '.join(decl)
    return '|%s#%s| "%s"%s' % (t, names[i], w, extra)


def link(a, b, ops=ops_simple, lab=0.25, along=0.0):
    s = '%s %s %s' % (a, R.choice(ops), b)
    if R.random() < lab:
        s += ' "%s"' % R.choice(labels)
        if R.random() < along:
            s += ' { along: %s }' % R.choice(['0.3', '0.35', '0.7', '0.25'])
    return s


def links_among(ids, m, **kw):
    out = []
    for _ in range(m):
        a, b = R.sample(ids, 2)
        out.append(link(a, b, **kw))
    return out


def scene_flat(kind, sizes=False, kinds=False, ops=ops_simple, nmin=2, nmax=6, mmin=1, mmax=5, lab=0.25, cfg=None):
    n = R.randint(nmin, nmax)
    lines = []
    decl = []
    if kind == 'col':
        decl.append('direction: column')
    elif kind == 'grid2':
        decl.append('layout: grid; columns: repeat(2)')
    elif kind == 'grid3':
        decl.append('layout: grid; columns: repeat(3)')
    if cfg:
        decl.extend(cfg)
    if decl:
        lines.append('{ %s }' % '; '.join(decl))
    for i in range(n):
        lines.append(node(i, sizes, kinds))
    m = R.randint(mmin, mmax)
    lines += links_among(names[:n], m, ops=ops, lab=lab)
    return '\n'.join(lines) + '\n'


def scene_groups():
    lines = []
    decl = []
    if R.random() < 0.3:
        decl.append('direction: column')
    if R.random() < 0.3:
        decl.append('clearance: %d' % R.choice([8, 12, 20]))
    if decl:
        lines.append('{ %s }' % '; '.join(decl))
    ng = R.randint(1, 3)
    ids = []
    k = 0
    for g in range(ng):
        gname = 'g%d' % g
        nb = R.randint(1, 3)
        gd = ' { direction: column }' if R.random() < 0.5 else ''
        cap = '\n  |caption| "Group %d"' % g if R.random() < 0.3 else ''
        body = []
        for j in range(nb):
            body.append('  ' + node(k))
            ids.append('%s.%s' % (gname, names[k]))
            k += 1
        lines.append('|group#%s|%s [%s\n%s\n]' % (gname, gd, cap, '\n'.join(body)))
    for j in range(R.randint(0, 2)):
        lines.append(node(k))
        ids.append(names[k])
        k += 1
    if len(ids) < 2:
        lines.append(node(k))
        ids.append(names[k])
        k += 1
    lines += links_among(ids, R.randint(1, 4))
    return '\n'.join(lines) + '\n'


def scene_fans():
    kind = R.choice(['row', 'col', 'grid2', 'grid3'])
    n = R.randint(3, 6)
    lines = []
    if kind == 'col':
        lines.append('{ direction: column }')
    elif kind == 'grid2':
        lines.append('{ layout: grid; columns: repeat(2) }')
    elif kind == 'grid3':
        lines.append('{ layout: grid; columns: repeat(3) }')
    for i in range(n):
        lines.append(node(i))
    ids = names[:n]
    for _ in range(R.randint(1, 3)):
        t = R.random()
        if t < 0.35:
            a = R.choice(ids)
            bs = R.sample([x for x in ids if x != a], R.randint(2, min(3, n - 1)))
            lines.append('%s %s %s' % (a, R.choice(['->', '->', '--', '<-']), ' & '.join(bs)))
        elif t < 0.6:
            b = R.choice(ids)
            as_ = R.sample([x for x in ids if x != b], R.randint(2, min(3, n - 1)))
            lines.append('%s %s %s' % (' & '.join(as_), R.choice(['->', '->', '--']), b))
        else:
            ch = R.sample(ids, R.randint(3, min(4, n)))
            lines.append((' %s ' % R.choice(['->', '->', '--'])).join(ch))
    return '\n'.join(lines) + '\n'


def scene_anchors():
    kind = R.choice(['row', 'col', 'grid2'])
    n = R.randint(2, 4)
    lines = []
    if kind == 'col':
        lines.append('{ direction: column }')
    elif kind == 'grid2':
        lines.append('{ layout: grid; columns: repeat(2) }')
    for i in range(n):
        lines.append(node(i))
    sides = ['top', 'right', 'bottom', 'left']
    for _ in range(R.randint(1, 3)):
        a, b = R.sample(names[:n], 2)
        sa = ':' + R.choice(sides) if R.random() < 0.7 else ''
        sb = ':' + R.choice(sides) if R.random() < 0.7 else ''
        lines.append('%s%s %s %s%s' % (a, sa, R.choice(ops_simple), b, sb))
    return '\n'.join(lines) + '\n'


def scene_settings():
    cfg = []
    if R.random() < 0.6:
        cfg.append('clearance: %d' % R.choice([6, 8, 10, 12, 20, 24]))
    if R.random() < 0.4:
        cfg.append('gap: %d' % R.choice([20, 30, 50, 80]))
    s = scene_flat(R.choice(['row', 'col', 'grid2', 'grid3']), cfg=cfg, nmin=2, nmax=5, mmin=1, mmax=4)
    if R.random() < 0.5:
        # per-link corner radius
        lines = s.split('\n')
        out = []
        for l in lines:
            if (' -> ' in l or ' <- ' in l or ' -- ' in l) and R.random() < 0.5 and '{' not in l:
                l += ' { corner-radius: %d }' % R.choice([0, 4, 8, 24])
            out.append(l)
        s = '\n'.join(out)
    return s


def scene_labels():
    kind = R.choice(['row', 'col', 'grid2', 'grid3'])
    n = R.randint(2, 5)
    lines = []
    if kind == 'col':
        lines.append('{ direction: column }')
    elif kind == 'grid2':
        lines.append('{ layout: grid; columns: repeat(2) }')
    elif kind == 'grid3':
        lines.append('{ layout: grid; columns: repeat(3) }')
    for i in range(n):
        lines.append(node(i))
    for _ in range(R.randint(1, 4)):
        a, b = R.sample(names[:n], 2)
        lines.append(link(a, b, lab=0.9, along=0.4))
    return '\n'.join(lines) + '\n'


out = []
for t in range(N):
    if fam == 'row':
        s = scene_flat('row')
    elif fam == 'col':
        s = scene_flat('col')
    elif fam == 'grid2':
        s = scene_flat('grid2', nmin=3, nmax=6)
    elif fam == 'grid3':
        s = scene_flat('grid3', nmin=4, nmax=9)
    elif fam == 'sizes':
        s = scene_flat(R.choice(['row', 'col', 'grid2', 'grid3']), sizes=True, nmin=2, nmax=6)
    elif fam == 'kinds':
        s = scene_flat(R.choice(['row', 'col', 'grid2', 'grid3']), kinds=True, ops=ops_all, nmin=2, nmax=6)
    elif fam == 'groups':
        s = scene_groups()
    elif fam == 'fans':
        s = scene_fans()
    elif fam == 'anchors':
        s = scene_anchors()
    elif fam == 'settings':
        s = scene_settings()
    elif fam == 'labels':
        s = scene_labels()
    elif fam == 'pair':
        s = scene_flat(R.choice(['row', 'col', 'grid2']), nmin=2, nmax=3, mmin=1, mmax=2)
    else:
        raise SystemExit('unknown family')
    out.append(s)
open(out_path, 'w').write('\n----\n'.join(out))

