# usage: probe.py 'src' ['src2' ...] : run the original on each snippet; print link paths (and warnings)
import subprocess, sys, os, re, tempfile
show_all = False
args = sys.argv[1:]
if args and args[0] == '-a':
    show_all = True
    args = args[1:]
mine = None
if args and args[0] == '-m':
    mine = '/tmp/bin-link2/executable'
    args = args[1:]
for src in args:
    src = src.replace('\\n', '\n')
    d = tempfile.mkdtemp(prefix='/tmp/link2/pp.')
    open(d + '/r_in.lini', 'w').write(src)
    r = subprocess.run(['/workspace/executable', 'r_in.lini'], capture_output=True, cwd=d)
    out = r.stdout.decode()
    print('### ' + src.replace('\n', ' | '))
    for l in r.stderr.decode().splitlines():
        print('   ERR ' + l)
    if show_all:
        print(out)
    else:
        for l in out.splitlines():
            if '<path d=' in l and 'lini-stray' not in l:
                m = re.search(r'd="([^"]*)"', l)
                print('   O ' + m.group(1))
            if 'data-from' in l:
                m = re.search(r'data-from="([^"]*)" data-to="([^"]*)"', l)
                print('   %s -> %s' % (m.group(1), m.group(2)))
    if mine:
        r2 = subprocess.run([mine, 'r_in.lini'], capture_output=True, cwd=d)
        if r2.stdout == r.stdout and r2.stderr == r.stderr:
            print('   (mine: SAME)')
        else:
            for l in r2.stderr.decode().splitlines():
                print('   MERR ' + l)
            for l in r2.stdout.decode().splitlines():
                if '<path d=' in l and 'lini-stray' not in l:
                    m = re.search(r'd="([^"]*)"', l)
                    print('   M ' + m.group(1))

