fn tb_mode() -> u32 {
    static M: std::sync::OnceLock<u32> = std::sync::OnceLock::new();
    *M.get_or_init(|| std::env::var("LINI_TB").ok().and_then(|s| s.parse().ok()).unwrap_or(0))
}

impl Ord for HeapItem {
    fn cmp(&self, o: &Self) -> std::cmp::Ordering {
        // min-heap on cost, then on insertion order
        let c = o.cost.partial_cmp(&self.cost).unwrap_or(std::cmp::Ordering::Equal);
        match tb_mode() {
            1 => c.then(o.seq.cmp(&self.seq)),
            2 => c.then(o.state.cmp(&self.state)),
            3 => c.then(self.state.cmp(&o.state)),
            _ => c.then(self.seq.cmp(&o.seq)),
        }
    }
}

