    pub lo: f64,
    pub hi: f64,
    pub count: usize,
}

// Port offsets per side of the two endpoints (default: side centre).
pub struct PortReq<'a> {
    pub sides_a: &'a [Side],
    pub sides_b: &'a [Side],
    // free width a channel must offer across every segment (bundles)
    pub need: f64,
    // runs other wires already hold
    pub taken: &'a [Taken],
}

// The free band across an axis-aligned segment: between the inflated
// obstacles on either side over the segment's span (infinite when open).
pub fn free_band(solids: &[Rect], p: (f64, f64), q: (f64, f64)) -> (f64, f64) {
    let horiz = (p.1 - q.1).abs() < 1e-9;
    let (lo_s, hi_s) = if horiz { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
    let pos = if horiz { p.1 } else { p.0 };
    let mut lo = f64::NEG_INFINITY;
    let mut hi = f64::INFINITY;
    for r in solids {
        let (a0, a1, b0, b1) = if horiz { (r.x0, r.x1, r.y0, r.y1) } else { (r.y0, r.y1, r.x0, r.x1) };
        if a0 < hi_s - EPS && a1 > lo_s + EPS {
            if b1 <= pos + EPS && b1 > lo {
                lo = b1;
            }
            if b0 >= pos - EPS && b0 < hi {
                hi = b0;
            }
        }
    }
    (lo, hi)
}

// Wires already running along the band [lo, hi] over the span of p-q.
pub fn taken_in(taken: &[Taken], p: (f64, f64), q: (f64, f64), lo: f64, hi: f64) -> usize {
    let horiz = (p.1 - q.1).abs() < 1e-9;
    let (s0, s1) = if horiz { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
    taken
        .iter()
        .filter(|t| t.horiz == horiz && t.lo < s1 - EPS && t.hi > s0 + EPS && t.pos > lo - EPS && t.pos < hi + EPS)
        .map(|t| t.count)
        .sum()
}

// Free width across an axis-aligned segment: the gap between the inflated
// obstacles on either side over the segment's span.
pub fn free_width(solids: &[Rect], p: (f64, f64), q: (f64, f64)) -> f64 {''')
