# usage: gen2.py FAMILY SEED N OUT  -- scenes with exactly M links (single / pair)
import random, sys

fam = sys.argv[1]
seed = int(sys.argv[2])
N = int(sys.argv[3])
out_path = sys.argv[4]
R = random.Random(seed * 7919 + sum(map(ord, fam)))
names = list('abcdefghijklmnop')
words = ['api', 'db', 'cache', 'queue', 'web', 'auth', 'svc', 'store', 'log', 'user', 'Gateway', 'x', 'Worker pool', 'f', 'iii']
ops = ['->', '->', '->', '<-', '<->', '--', '-->']


def scene(nlinks, anchors=0.0, sizes=0.0):
    kind = R.choice(['row', 'col', 'grid2', 'grid3', 'grid3'])
    if kind == 'row':
        n = R.randint(2, 5)
    elif kind == 'col':
        n = R.randint(2, 4)
    elif kind == 'grid2':
        n = R.randint(3, 6)
    else:
        n = R.randint(4, 9)
    lines = []
    if kind == 'col':
        lines.append('{ direction: column }')
    elif kind == 'grid2':
        lines.append('{ layout: grid; columns: repeat(2) }')
    elif kind == 'grid3':
        lines.append('{ layout: grid; columns: repeat(3) }')
    for i in range(n):
        extra = ''
        if R.random() < sizes:
            decl = []
            if R.random() < 0.5:
                decl.append('width: %d' % R.choice([40, 60, 80, 100, 140]))
            else:
                decl.append('height: %d' % R.choice([30, 40, 80, 100]))
            extra = ' { %s }' % '; '.join(decl)
        lines.append('|box#%s| "%s"%s' % (names[i], R.choice(words), extra))
    sides = ['top', 'right', 'bottom', 'left']
    for _ in range(nlinks):
        a, b = R.sample(names[:n], 2)
        sa = ':' + R.choice(sides) if R.random() < anchors else ''
        sb = ':' + R.choice(sides) if R.random() < anchors else ''
        lines.append('%s%s %s %s%s' % (a, sa, R.choice(ops), b, sb))
    return '\n'.join(lines) + '\n'


out = []
