        s = scene(2)
    elif fam == 'two_anch':
        s = scene(2, anchors=0.5)
    elif fam == 'three':
        s = scene(3)
    else:
        raise SystemExit('unknown')
    out.append(s)
open(out_path, 'w').write('\n----\n'.join(out))

