// The separation law: wires of two links keep half a clearance apart. Each
// pair of links reports its first pair of segments (polyline corner to
// corner) that come closer without crossing.
fn separation_warnings(ctx: &mut Ctx, geos: &[LinkGeo]) {
    let segs = |g: &LinkGeo| -> Vec<((f64, f64), (f64, f64))> {
        if g.stray || g.curve.is_some() || g.pts.len() < 2 {
            return vec![];
        }
        g.pts.windows(2).map(|w| (w[0], w[1])).collect()
    };
    let dist = |a: ((f64, f64), (f64, f64)), b: ((f64, f64), (f64, f64))| -> f64 {
        let (ax0, ax1) = (a.0 .0.min(a.1 .0), a.0 .0.max(a.1 .0));
        let (ay0, ay1) = (a.0 .1.min(a.1 .1), a.0 .1.max(a.1 .1));
        let (bx0, bx1) = (b.0 .0.min(b.1 .0), b.0 .0.max(b.1 .0));
        let (by0, by1) = (b.0 .1.min(b.1 .1), b.0 .1.max(b.1 .1));
        let dx = (bx0 - ax1).max(ax0 - bx1).max(0.0);
        let dy = (by0 - ay1).max(ay0 - by1).max(0.0);
        if dx == 0.0 {
            dy
        } else if dy == 0.0 {
            dx
        } else {
            (dx * dx + dy * dy).sqrt()
        }
    };
    let name = |ctx: &Ctx, li: usize| format!("{} -> {}", path_of(ctx, ctx.links[li].from), path_of(ctx, ctx.links[li].to));
    let fmt_seg = |s: ((f64, f64), (f64, f64))| format!("[({:?}, {:?}), ({:?}, {:?})]", s.0 .0, s.0 .1, s.1 .0, s.1 .1);
    let mut out: Vec<Diag> = Vec::new();
    for i in 0..geos.len() {
        let si = segs(&geos[i]);
        if si.is_empty() {
            continue;
        }
        for j in i + 1..geos.len() {
            let sj = segs(&geos[j]);
            if sj.is_empty() {
                continue;
            }
            let floor = geos[i].style.k.min(geos[j].style.k) / 2.0;
            let mut hit = None;
            'find: for &a in &si {
                for &b in &sj {
                    let d = dist(a, b);
                    if d > 0.0 && d < floor - 1e-9 {
                        hit = Some((a, b, d));
                        break 'find;
                    }
                }
            }
            if let Some((a, b, d)) = hit {
                let msg = format!(
                    "separation ({}, {}): segments {} and {} are {} apart, below the half-clearance floor {}",
                    name(ctx, geos[i].li),
                    name(ctx, geos[j].li),
                    fmt_seg(a),
                    fmt_seg(b),
                    d,
                    floor
                );
                out.push(Diag::warning("law-breach", &msg, ctx.links[geos[j].li].span));
            }
        }
    }
    ctx.warnings.extend(out);
}

