// Record a planned bundle route: its side slots, U channels and runs.
fn record(occ: &mut Occupancy, env: &Env, b: &Bundle, keys: &(Vec<i64>, Vec<i64>), path: &Path) {
    let n = b.reqs.len();
    for (node, side, ks) in [(b.p, path.sa, &keys.0), (b.q, path.sb, &keys.1)] {
