import sys, subprocess, re, os, tempfile, hashlib, pickle
from concurrent.futures import ThreadPoolExecutor
MINE = '/tmp/bin-link2/executable'
CACHE = '/tmp/link2/cache'
args = sys.argv[1:]
verbose = False
