def run(b, src):
    d = tempfile.mkdtemp(prefix='/tmp/link2/rr.')
    p = d + '/r_in.lini'
    open(p, 'w').write(src)
    r = subprocess.run([b, 'r_in.lini'], capture_output=True, cwd=d, timeout=60)
    os.remove(p)
    os.rmdir(d)
    return (r.stdout, r.stderr, r.returncode)


def orig(src):
    h = hashlib.sha1(src.encode()).hexdigest()
    cp = CACHE + '/' + h
    if os.path.exists(cp):
        try:
            return pickle.load(open(cp, 'rb'))
        except Exception:
            pass
    r = run('/workspace/executable', src)
    pickle.dump(r, open(cp, 'wb'))
    return r


def links(out):
    res = []
    cur = None
    for l in out.splitlines():
        m = re.search(r'<g class="lini-(link|stray)[^"]*"[^>]*data-from="([^"]*)" data-to="([^"]*)"', l)
        if m:
            cur = [m.group(1) + ':' + m.group(2) + '->' + m.group(3), None]
            res.append(cur)
            continue
        m = re.search(r'<path d="([^"]*)"', l)
        if m and cur is not None and cur[1] is None:
            cur[1] = m.group(1)
    return res


def topo(d):
    if d is None:
        return None
    nums = re.findall(r'[MLA]|-?[0-9.]+', d)
    pts = []
    i = 0
    while i < len(nums):
        t = nums[i]
        if t in ('M', 'L'):
            pts.append((float(nums[i + 1]), float(nums[i + 2])))
            i += 3
        elif t == 'A':
            pts.append((float(nums[i + 6]), float(nums[i + 7])))
            i += 8
        else:
            i += 1
    dirs = []
    for a, b in zip(pts, pts[1:]):
        dx, dy = b[0] - a[0], b[1] - a[1]
        if abs(dx) < 1e-6 and abs(dy) < 1e-6:
            continue
        if abs(dx) > 1e-6 and abs(dy) > 1e-6:
            dd = ('R' if dx > 0 else 'L') + ('D' if dy > 0 else 'U')
        elif abs(dx) > 1e-6:
            dd = 'R' if dx > 0 else 'L'
        else:
            dd = 'D' if dy > 0 else 'U'
        if not dirs or dirs[-1] != dd:
            dirs.append(dd)
    return ''.join(dirs)


def one(s):
    a = orig(s)
    b = run(MINE, s)
    if a == b:
        return ('=', '')
    la = links(a[0].decode(errors='replace'))
    lb = links(b[0].decode(errors='replace'))
    if len(la) != len(lb):
        return ('count', '')
    route = []
    geom = []
    for x, y in zip(la, lb):
        if x == y:
            continue
        if x[0] != y[0]:
            route.append(x[0] + '/' + y[0])
        elif topo(x[1]) != topo(y[1]):
            route.append('%s %s/%s' % (x[0], topo(x[1]), topo(y[1])))
        else:
            geom.append(x[0])
    if route:
        return ('route', '; '.join(route))
    if geom:
        return ('geom', ', '.join(geom))
    if a[1] != b[1]:
        return ('stderr', '')
    return ('other', '')


tot = {}
with ThreadPoolExecutor(max_workers=16) as ex:
    for f in args:
        snips = [s for s in open(f).read().split('\n----\n') if s.strip()]
        res = list(ex.map(one, snips))
        c = {}
        for i, (k, info) in enumerate(res):
