#!/usr/bin/env python3
# Generic threshold finder.
# usage: bis.py "template with {P}" lo hi [tol]
# Classifies the original's first link path by its direction string (e.g. "RDL") and bisects on P
# between lo and hi where the class changes. Prints the classes and the threshold.
import subprocess, re, os, tempfile, sys
tmpl = sys.argv[1].replace('\\n', '\n')
lo, hi = float(sys.argv[2]), float(sys.argv[3])
tol = float(sys.argv[4]) if len(sys.argv) > 4 else 1e-3
idx = int(os.environ.get('LINK', '0'))


def run(src):
    d = tempfile.mkdtemp(prefix='/tmp/link2/bs.')
    open(d + '/r_in.lini', 'w').write(src)
    r = subprocess.run(['/workspace/executable', 'r_in.lini'], capture_output=True, cwd=d)
    os.remove(d + '/r_in.lini')
    os.rmdir(d)
    return r.stdout.decode()


def topo(d):
    nums = re.findall(r'[MLA]|-?[0-9.]+', d)
    pts = []
    i = 0
    while i < len(nums):
        t = nums[i]
        if t in ('M', 'L'):
            pts.append((float(nums[i + 1]), float(nums[i + 2])))
            i += 3
        elif t == 'A':
            pts.append((float(nums[i + 6]), float(nums[i + 7])))
            i += 8
        else:
            i += 1
    dirs = []
    for a, b in zip(pts, pts[1:]):
        dx, dy = b[0] - a[0], b[1] - a[1]
        if abs(dx) < 1e-6 and abs(dy) < 1e-6:
            continue
        if abs(dx) > 1e-6 and abs(dy) > 1e-6:
            dd = ('R' if dx > 0 else 'L') + ('D' if dy > 0 else 'U')
        elif abs(dx) > 1e-6:
            dd = 'R' if dx > 0 else 'L'
        else:
            dd = 'D' if dy > 0 else 'U'
        if not dirs or dirs[-1] != dd:
            dirs.append(dd)
    return ''.join(dirs)


def cls(p):
    o = run(tmpl.replace('{P}', '%.6f' % p))
    ds = re.findall(r'<path d="(M[^"]*)"', o)
    if not ds:
        return 'none'
    return topo(ds[idx])


clo, chi = cls(lo), cls(hi)
if clo == chi:
    print('same class %s at both ends' % clo)
    sys.exit(0)
while hi - lo > tol:
    mid = (lo + hi) / 2
    c = cls(mid)
    if c == clo:
        lo = mid
    elif c == chi:
        hi = mid
    else:
        print('third class %s at %.6f' % (c, mid))
        hi = mid
        chi = c
print('%.4f  %s -> %s' % ((lo + hi) / 2, clo, chi))

