    // Inflated solid obstacles (including the two endpoints).
    pub fn solids(&self) -> Vec<Rect> {
        let mut v: Vec<Rect> = self.obs.iter().filter(|o| o.kind != ObKind::WallBoth).map(|o| o.r.grow(self.k)).collect();
