#!/usr/bin/env python3
# Simulate candidate Dijkstra tie-break schemes on a column a, b, c (a -> c) and compare the
# L/R outcome with the original's (read from lrg1.txt).
import re, heapq, itertools, sys

K = 16.0
H = 57.0  # outer heights (55 + stroke)
GAP = 36.0


def scene(wa, wb, wc):
    # outer half widths (+1 stroke)
    ha, hb, hc = wa / 2 + 1, wb / 2 + 1, wc / 2 + 1
    ya, yb, yc = -93.0, 0.0, 93.0
    boxes = [(-ha, ya - H / 2, ha, ya + H / 2), (-hb, yb - H / 2, hb, yb + H / 2), (-hc, yc - H / 2, hc, yc + H / 2)]
    return boxes


def grow(r, k=K):
    return (r[0] - k, r[1] - k, r[2] + k, r[3] + k)


def inside(r, x, y):
    e = 1e-9
    return r[0] + e < x < r[2] - e and r[1] + e < y < r[3] - e


def seg_ok(solids, p, q):
    for r in solids:
        if abs(p[1] - q[1]) < 1e-9:
            y = p[1]
            x0, x1 = min(p[0], q[0]), max(p[0], q[0])
            if r[1] + 1e-9 < y < r[3] - 1e-9 and x0 < r[2] - 1e-9 and x1 > r[0] + 1e-9:
                return False
        else:
            x = p[0]
            y0, y1 = min(p[1], q[1]), max(p[1], q[1])
            if r[0] + 1e-9 < x < r[2] - 1e-9 and y0 < r[3] - 1e-9 and y1 > r[1] + 1e-9:
                return False
    return True


DIRS = {'E': (1, 0), 'S': (0, 1), 'W': (-1, 0), 'N': (0, -1)}
SIDE_DIR = {'R': 'E', 'B': 'S', 'L': 'W', 'T': 'N'}
OPP = {'E': 'W', 'W': 'E', 'S': 'N', 'N': 'S'}


def run(boxes, src_order, nb_order, tb, end_mode, dir_index, major):
    solids = [grow(b) for b in boxes]
    a, c = boxes[0], boxes[2]
    acx, acy = (a[0] + a[2]) / 2, (a[1] + a[3]) / 2
    ccx, ccy = (c[0] + c[2]) / 2, (c[1] + c[3]) / 2

    def stub(r, side):
        cx, cy = (r[0] + r[2]) / 2, (r[1] + r[3]) / 2
        if side == 'R':
            return (r[2], cy), (r[2] + K, cy)
        if side == 'L':
