#!/usr/bin/env python3
# Simulate candidate Dijkstra tie-break schemes on a column a, b, c (a -> c) and compare the
# L/R outcome with the original's (read from lrg1.txt).
import re, heapq, itertools, sys

K = 16.0
H = 57.0  # outer heights (55 + stroke)
GAP = 36.0


def scene(wa, wb, wc):
    # outer half widths (+1 stroke)
    ha, hb, hc = wa / 2 + 1, wb / 2 + 1, wc / 2 + 1
    ya, yb, yc = -93.0, 0.0, 93.0
    boxes = [(-ha, ya - H / 2, ha, ya + H / 2), (-hb, yb - H / 2, hb, yb + H / 2), (-hc, yc - H / 2, hc, yc + H / 2)]
    return boxes


def grow(r, k=K):
    return (r[0] - k, r[1] - k, r[2] + k, r[3] + k)


def inside(r, x, y):
    e = 1e-9
    return r[0] + e < x < r[2] - e and r[1] + e < y < r[3] - e


def seg_ok(solids, p, q):
    for r in solids:
        if abs(p[1] - q[1]) < 1e-9:
            y = p[1]
            x0, x1 = min(p[0], q[0]), max(p[0], q[0])
            if r[1] + 1e-9 < y < r[3] - 1e-9 and x0 < r[2] - 1e-9 and x1 > r[0] + 1e-9:
                return False
        else:
            x = p[0]
            y0, y1 = min(p[1], q[1]), max(p[1], q[1])
            if r[0] + 1e-9 < x < r[2] - 1e-9 and y0 < r[3] - 1e-9 and y1 > r[1] + 1e-9:
                return False
    return True


DIRS = {'E': (1, 0), 'S': (0, 1), 'W': (-1, 0), 'N': (0, -1)}
SIDE_DIR = {'R': 'E', 'B': 'S', 'L': 'W', 'T': 'N'}
OPP = {'E': 'W', 'W': 'E', 'S': 'N', 'N': 'S'}


def run(boxes, src_order, nb_order, tb, end_mode, dir_index, major):
    solids = [grow(b) for b in boxes]
    a, c = boxes[0], boxes[2]
    acx, acy = (a[0] + a[2]) / 2, (a[1] + a[3]) / 2
    ccx, ccy = (c[0] + c[2]) / 2, (c[1] + c[3]) / 2

    def stub(r, side):
        cx, cy = (r[0] + r[2]) / 2, (r[1] + r[3]) / 2
        if side == 'R':
            return (r[2], cy), (r[2] + K, cy)
        if side == 'L':
            return (r[0], cy), (r[0] - K, cy)
        if side == 'B':
            return (cx, r[3]), (cx, r[3] + K)
        return (cx, r[1]), (cx, r[1] - K)
    xs, ys = set(), set()
    for r in solids:
        xs.update([r[0], r[2]])
        ys.update([r[1], r[3]])
    xs.update([acx, ccx])
    ys.update([acy, ccy])
    for r in (a, c):
        for s in 'RBLT':
            _, e = stub(r, s)
            xs.add(e[0])
            ys.add(e[1])
    xs = sorted(xs)
    ys = sorted(ys)
    nx, ny = len(xs), len(ys)

    def vid(i, j):
        return j * nx + i if major == 'row' else i * ny + j
    dirs_list = list(dir_index)
    di = {d: n for n, d in enumerate(dirs_list)}

    def sid(i, j, d):
        return vid(i, j) * 4 + di[d]
    free = {}
    for i in range(nx):
        for j in range(ny):
            free[(i, j)] = not any(inside(r, xs[i], ys[j]) for r in solids)
    starts = []
    for s in src_order:
        p, e = stub(a, s)
        if e[0] in xs and e[1] in ys:
            starts.append((s, xs.index(e[0]), ys.index(e[1])))
    ends = {}
    for s in 'RBLT':
        p, e = stub(c, s)
        ends[(xs.index(e[0]), ys.index(e[1]))] = s
    dist = {}
    prev = {}
    heap = []
    cnt = itertools.count()

    def push(cost, i, j, d):
        st = sid(i, j, d)
        if tb == 'fifo':
            key = (cost, next(cnt))
        elif tb == 'lifo':
            key = (cost, -next(cnt))
        elif tb == 'small':
            key = (cost, st)
        else:
            key = (cost, -st)
        heapq.heappush(heap, (key, i, j, d))
    for s, i, j in starts:
        d = SIDE_DIR[s]
        dist[(i, j, d)] = K
        prev[(i, j, d)] = ('start', s)
        push(K, i, j, d)
    best = None
    while heap:
        key, i, j, d = heapq.heappop(heap)
        cost = key[0]
        if cost > dist[(i, j, d)] + 1e-9:
            continue
        if best is not None and cost > best[0] + 1e-9:
            break
        if (i, j) in ends:
            s = ends[(i, j)]
            need = OPP[SIDE_DIR[s]]
            if d != OPP[need]:
                c2 = cost + K + (0 if d == need else 2 * K)
                if best is None or c2 < best[0] - 1e-9:
                    best = (c2, i, j, d, s)
                    if end_mode == 'first':
                        break
        for nd in nb_order:
            if nd == OPP[d]:
                continue
            dx, dy = DIRS[nd]
            if dx:
                ni, nj = i + dx, j
            else:
                ni, nj = i, j + dy
            if not (0 <= ni < nx and 0 <= nj < ny):
                continue
            if not free[(ni, nj)]:
                continue
            p, q = (xs[i], ys[j]), (xs[ni], ys[nj])
            if not seg_ok(solids, p, q):
                continue
            nc = cost + abs(q[0] - p[0]) + abs(q[1] - p[1]) + (0 if nd == d else 2 * K)
            key2 = (ni, nj, nd)
            if nc < dist.get(key2, 1e18) - 1e-9:
                dist[key2] = nc
                prev[key2] = (i, j, d)
                push(nc, ni, nj, nd)
    if best is None:
        return '--'
    # trace back the start side
    cur = (best[1], best[2], best[3])
    while True:
        pv = prev[cur]
        if pv[0] == 'start':
            return pv[1] + best[4]
        cur = pv


