#!/usr/bin/env python3
# Orthogonal visibility graph + Dijkstra tie-break simulation for column/row U choices.
import re, heapq, itertools, sys

K = 16.0
INF = 1e9
DIRS = {'E': (1, 0), 'S': (0, 1), 'W': (-1, 0), 'N': (0, -1)}
SIDE_DIR = {'R': 'E', 'B': 'S', 'L': 'W', 'T': 'N'}
OPP = {'E': 'W', 'W': 'E', 'S': 'N', 'N': 'S'}
DIR_IDX = {'E': 0, 'S': 1, 'W': 2, 'N': 3}


def grow(r, k=K):
    return (r[0] - k, r[1] - k, r[2] + k, r[3] + k)


def ray_extent(solids, x, y0, y1, vertical):
    # extend the segment [y0, y1] at x (vertical) until hitting a solid whose span strictly contains x
    lo, hi = y0, y1
    best_lo, best_hi = -INF, INF
    for r in solids:
        if vertical:
            if r[0] + 1e-9 < x < r[2] - 1e-9:
                if r[3] <= lo + 1e-9:
                    best_lo = max(best_lo, r[3])
                elif r[1] >= hi - 1e-9:
                    best_hi = min(best_hi, r[1])
        else:
            if r[1] + 1e-9 < x < r[3] - 1e-9:
                if r[2] <= lo + 1e-9:
                    best_lo = max(best_lo, r[2])
                elif r[0] >= hi - 1e-9:
                    best_hi = min(best_hi, r[0])
    return best_lo, best_hi


def build(boxes, src, dst, ovg=True):
    solids = [grow(b) for b in boxes]
    a, c = boxes[src], boxes[dst]

    def stub(r, side):
        cx, cy = (r[0] + r[2]) / 2, (r[1] + r[3]) / 2
        if side == 'R':
            return (r[2], cy), (r[2] + K, cy)
        if side == 'L':
            return (r[0], cy), (r[0] - K, cy)
        if side == 'B':
            return (cx, r[3]), (cx, r[3] + K)
        return (cx, r[1]), (cx, r[1] - K)
    vsegs = []  # (x, ylo, yhi)
    hsegs = []  # (y, xlo, xhi)
    for g in solids:
        for x in (g[0], g[2]):
            lo, hi = ray_extent(solids, x, g[1], g[3], True) if ovg else (-INF, INF)
            vsegs.append((x, lo, hi))
        for y in (g[1], g[3]):
            lo, hi = ray_extent(solids, y, g[0], g[2], False) if ovg else (-INF, INF)
            hsegs.append((y, lo, hi))
    # port rays: from each stub end outwards, and the port axis lines
    for r in (a, c):
        for s in 'RBLT':
            p, e = stub(r, s)
            if s in 'RL':
                lo, hi = ray_extent(solids, e[1], e[0], e[0], False) if ovg else (-INF, INF)
                hsegs.append((e[1], lo, hi))
                lo, hi = ray_extent(solids, e[0], e[1], e[1], True) if ovg else (-INF, INF)
                vsegs.append((e[0], lo, hi))
            else:
                lo, hi = ray_extent(solids, e[0], e[1], e[1], True) if ovg else (-INF, INF)
                vsegs.append((e[0], lo, hi))
                lo, hi = ray_extent(solids, e[1], e[0], e[0], False) if ovg else (-INF, INF)
                hsegs.append((e[1], lo, hi))
    verts = set()
    for (x, ylo, yhi) in vsegs:
        for (y, xlo, xhi) in hsegs:
            if ylo - 1e-9 <= y <= yhi + 1e-9 and xlo - 1e-9 <= x <= xhi + 1e-9:
                if not any(g[0] + 1e-9 < x < g[2] - 1e-9 and g[1] + 1e-9 < y < g[3] - 1e-9 for g in solids):
                    verts.add((round(x, 9), round(y, 9)))
    # adjacency along segments
    adj = {v: {} for v in verts}

    def link(v, w, d):
        adj[v][d] = w
    for (x, ylo, yhi) in vsegs:
        col = sorted([v for v in verts if abs(v[0] - x) < 1e-9 and ylo - 1e-9 <= v[1] <= yhi + 1e-9], key=lambda v: v[1])
        for p, q in zip(col, col[1:]):
            if not seg_blocked(solids, p, q):
                link(p, q, 'S')
                link(q, p, 'N')
    for (y, xlo, xhi) in hsegs:
        row = sorted([v for v in verts if abs(v[1] - y) < 1e-9 and xlo - 1e-9 <= v[0] <= xhi + 1e-9], key=lambda v: v[0])
        for p, q in zip(row, row[1:]):
            if not seg_blocked(solids, p, q):
                link(p, q, 'E')
                link(q, p, 'W')
    starts = []
    for s in 'RBLT':
        p, e = stub(a, s)
        ev = (round(e[0], 9), round(e[1], 9))
        if ev in verts:
            starts.append((s, ev))
    ends = {}
    for s in 'RBLT':
        p, e = stub(c, s)
        ev = (round(e[0], 9), round(e[1], 9))
        if ev in verts:
            ends[ev] = s
    return verts, adj, starts, ends


def seg_blocked(solids, p, q):
    for r in solids:
        if abs(p[1] - q[1]) < 1e-9:
            y = p[1]
            x0, x1 = min(p[0], q[0]), max(p[0], q[0])
            if r[1] + 1e-9 < y < r[3] - 1e-9 and x0 < r[2] - 1e-9 and x1 > r[0] + 1e-9:
                return True
        else:
            x = p[0]
            y0, y1 = min(p[1], q[1]), max(p[1], q[1])
            if r[0] + 1e-9 < x < r[2] - 1e-9 and y0 < r[3] - 1e-9 and y1 > r[1] + 1e-9:
                return True
    return False


def search(boxes, src, dst, src_order='RBLT', tb='hd_vdesc', end_mode='push', ovg=True, nb_order='ESWN'):
    verts, adj, starts, ends = build(boxes, src, dst, ovg)
    vl = sorted(verts, key=lambda v: (v[1], v[0]))
    vid = {v: n for n, v in enumerate(vl)}
    order = {s: n for n, s in enumerate(src_order)}
    starts.sort(key=lambda t: order[t[0]])
    dist, prev = {}, {}
    heap = []
    cnt = itertools.count()

    def key(cost, v, d):
        if tb == 'hd_vdesc':
            return (cost, DIR_IDX[d], -vid[v])
        if tb == 'hd_vasc':
            return (cost, DIR_IDX[d], vid[v])
        if tb == 'small':
            return (cost, vid[v] * 4 + DIR_IDX[d])
        if tb == 'large':
            return (cost, -(vid[v] * 4 + DIR_IDX[d]))
        if tb == 'fifo':
            return (cost, next(cnt))
        return (cost, -next(cnt))
    for s, v in starts:
        d = SIDE_DIR[s]
        dist[(v, d)] = K
        prev[(v, d)] = ('start', s)
        heapq.heappush(heap, (key(K, v, d), K, v, d))
    best = None
    while heap:
        _, cost, v, d = heapq.heappop(heap)
        if cost > dist[(v, d)] + 1e-9:
            continue
        if best is not None and cost > best[0] + 1e-9:
            break
        if end_mode == 'pop' and v in ends:
            s = ends[v]
            need = OPP[SIDE_DIR[s]]
            if d != OPP[need]:
                c2 = cost + K + (0 if d == need else 2 * K)
                if best is None or c2 < best[0] - 1e-9:
                    best = (c2, v, d, s)
        for nd in nb_order:
            if nd == OPP[d] or nd not in adj[v]:
                continue
            w = adj[v][nd]
            nc = cost + abs(w[0] - v[0]) + abs(w[1] - v[1]) + (0 if nd == d else 2 * K)
            if end_mode == 'push' and w in ends:
                s2 = ends[w]
                need = OPP[SIDE_DIR[s2]]
                if nd != OPP[need]:
                    c2 = nc + K + (0 if nd == need else 2 * K)
                    if best is None or c2 < best[0] - 1e-9:
                        best = (c2, w, nd, s2)
                        prev[('end', w, nd)] = (v, d)
            if nc < dist.get((w, nd), 1e18) - 1e-9:
                dist[(w, nd)] = nc
                prev[(w, nd)] = (v, d)
                heapq.heappush(heap, (key(nc, w, nd), nc, w, nd))
    if best is None:
        return '--'
    if end_mode == 'push':
        cur = prev[('end', best[1], best[2])]
    else:
        cur = (best[1], best[2])
    while True:
        pv = prev[cur]
        if pv[0] == 'start':
            return pv[1] + best[3]
        cur = pv


def col_scene(wa, wb, wc, ha=55, hb=55, hc=55):
    ys = []
    y = 0.0
    hs = [ha + 2, hb + 2, hc + 2]
    # column: centres separated by half heights + gap 36
    cy = [0.0]
    for i in range(1, 3):
        cy.append(cy[-1] + hs[i - 1] / 2 + 36 + hs[i] / 2)
    off = (cy[0] + cy[2]) / 2
    boxes = []
    for w, h, y in zip((wa, wb, wc), hs, cy):
        boxes.append((-(w / 2 + 1), y - off - h / 2, w / 2 + 1, y - off + h / 2))
    return boxes


def row_scene(ha, hb, hc, w=60):
    boxes = []
    xs = [0.0, w + 2 + 36, 2 * (w + 2 + 36)]
    off = xs[1]
    for h, x in zip((ha, hb, hc), xs):
        boxes.append((x - off - (w / 2 + 1), -(h / 2 + 1), x - off + (w / 2 + 1), h / 2 + 1))
    return boxes


if __name__ == '__main__':
    combos = []
    for src_order in ['RBLT']:
        for tb in ['hd_vdesc', 'hd_vasc', 'small', 'large', 'fifo']:
            for end_mode in ['push', 'pop']:
                for ovg in [True, False]:
                    combos.append((src_order, tb, end_mode, ovg))
    data = []
    for l in open('/tmp/link2/lrg1.txt'):
        m = re.match(r'a=\s*(\d+) b=\s*(\d+) c=\s*(\d+)\s+(\S+)', l)
        a, b, c, cls = int(m.group(1)), int(m.group(2)), int(m.group(3)), m.group(4)
        if cls in ('LL', 'RR'):
            data.append(('col', (a, b, c), cls))
    for l in open('/tmp/link2/udg1.txt'):
        m = re.match(r'a=\s*(\d+) b=\s*(\d+) c=\s*(\d+)\s+(\S+)', l)
        a, b, c, cls = int(m.group(1)), int(m.group(2)), int(m.group(3)), m.group(4)
        if cls in ('TT', 'BB'):
            data.append(('row', (a, b, c), cls))
    for combo in combos:
        ok = 0
        bad = []
        for kind, (a, b, c), cls in data:
            boxes = col_scene(a, b, c) if kind == 'col' else row_scene(a, b, c)
            r = search(boxes, 0, 2, *combo)
            if r == cls:
                ok += 1
            else:
                bad.append((kind, a, b, c, cls, r))
        print(combo, ok, '/', len(data), bad[:4])

