#!/usr/bin/env python3
# Replicates the mask id hash: FNV-1a 64 folded to 32 bits over a Rust-{:?}-formatted key.
import sys, struct


def fnv(s):
    h = 0xcbf29ce484222325
    for b in s.encode():
        h ^= b
        h = (h * 0x100000001b3) & 0xffffffffffffffff
    return '%08x' % (((h >> 32) ^ h) & 0xffffffff)


def rf(x):
    # Rust {:?} for f64: shortest round-trip repr, always with a decimal point
    if x == int(x) and abs(x) < 1e16:
        return '%d.0' % int(x) if x != 0 or str(x)[0] != '-' else '-0.0'
    r = repr(x)
    if 'e' in r:
        m, e = r.split('e')
        e = int(e)
        return '%se%d' % (m, e)
    return r


def key(x0, y0, w, h, cuts):
    cs = ', '.join('(%s, %s, %s, %s)' % tuple(rf(v) for v in c) for c in cuts)
    return '%s %s %s %s [%s]' % (rf(x0), rf(y0), rf(w), rf(h), cs)


def nb(x, k=1):
    # k-th float neighbours
    out = [x]
    a = b = x
    for _ in range(k):
        a = struct.unpack('<d', struct.pack('<q', struct.unpack('<q', struct.pack('<d', a))[0] - 1))[0] if a > 0 else struct.unpack('<d', struct.pack('<q', struct.unpack('<q', struct.pack('<d', a))[0] + 1))[0]
        b = struct.unpack('<d', struct.pack('<q', struct.unpack('<q', struct.pack('<d', b))[0] + 1))[0] if b > 0 else struct.unpack('<d', struct.pack('<q', struct.unpack('<q', struct.pack('<d', b))[0] - 1))[0]
        out += [a, b]
    return out


if __name__ == '__main__':
