    let n = pts.len();
    let mut poly: Vec<(f64, f64)> = vec![pts[0]];
    for i in 1..n - 1 {
        let (p, c, q) = (pts[i - 1], pts[i], pts[i + 1]);
        let u0 = unitv(p, c);
        let u1 = unitv(c, q);
        let r = radii.get(i - 1).copied().unwrap_or(0.0);
        let a = (c.0 - u0.0 * r, c.1 - u0.1 * r);
        let b = (c.0 + u1.0 * r, c.1 + u1.1 * r);
        let last = *poly.last().unwrap();
        if (a.0 - last.0).powi(2) + (a.1 - last.1).powi(2) > 1e-18 {
            poly.push(a);
        }
