            let nrm = if left { (-u0.1, u0.0) } else { (u0.1, -u0.0) };
            let ctr = (a.0 + nrm.0 * r, a.1 + nrm.1 * r);
            let a0 = (a.1 - ctr.1).atan2(a.0 - ctr.0);
            let arc = std::f64::consts::PI * r / 2.0;
            let steps = (arc / 1.5).ceil().max(1.0) as usize;
            for j in 1..=steps {
                let th = std::f64::consts::FRAC_PI_2 * j as f64 / steps as f64;
                let ang = if left { a0 + th } else { a0 - th };
                poly.push((ctr.0 + r * ang.cos(), ctr.1 + r * ang.sin()));
            }
        }
    }
    poly.push(pts[n - 1]);
    let mut cum = vec![0.0];
    for w in poly.windows(2) {
        let l = cum.last().unwrap() + ((w[1].0 - w[0].0).powi(2) + (w[1].1 - w[0].1).powi(2)).sqrt();
        cum.push(l);
    }
    let l = *cum.last().unwrap();
    // the base point and direction at distance x along the polyline
    let at = |x: f64| -> ((f64, f64), (f64, f64)) {
        let m = poly.len();
        for i in 0..m - 1 {
            if x <= cum[i + 1] || i == m - 2 {
                let u = unitv(poly[i], poly[i + 1]);
                let t = x - cum[i];
                return ((poly[i].0 + u.0 * t, poly[i].1 + u.1 * t), u);
            }
        }
        (poly[m - 1], (1.0, 0.0))
    };
    let amp = 1.4;
    let lam = 12.0;
    let ramp = 6.0;
    let cnt = ((l / 3.0).round() as usize).max(1);
    let h = l / cnt as f64;
    let ss = |t: f64| {
        let t = t.clamp(0.0, 1.0);
        3.0 * t * t - 2.0 * t * t * t
    };
    let dss = |t: f64| if t <= 0.0 || t >= 1.0 { 0.0 } else { 6.0 * t - 6.0 * t * t };
    let w = 2.0 * std::f64::consts::PI / lam;
    // (wave point, its tangent) per sample
    let mut samples: Vec<((f64, f64), (f64, f64))> = Vec::new();
    for i in 0..=cnt {
        let x = i as f64 * h;
        let e1 = ss(x / ramp);
        let e2 = ss((l - x) / ramp);
        let (e, de) = if e1 < e2 { (e1, dss(x / ramp) / ramp) } else { (e2, -dss((l - x) / ramp) / ramp) };
        let y = amp * e * (w * x).sin();
        let dy = amp * (de * (w * x).sin() + e * w * (w * x).cos());
