        let ln = (1.0 + dy * dy).sqrt();
        samples.push((p, ((u.0 + nrm.0 * dy) / ln, (u.1 + nrm.1 * dy) / ln)));
    }
    let mut d = format!("M {} {}", f4(pts[0].0), f4(pts[0].1));
    for i in 0..cnt {
